(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c8"]=[{"id":"00002734","register_sub_id":"101","register_pk":"103724","name":"遺愛学院講堂","kana":"いあいがくいんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道函館市杉並町64-1","lat":41.787518,"lng":140.757172,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部2階建、亜鉛葺、建築面積467㎡","structure_material":"木造平屋一部2階建","registered":"2002.06.25(平成14.06.25)","register_no":"01 － 0049","desc":"ヴォーリズ建築事務所の設計。本館内にあった既存講堂が手狭になったため，宣教師からの寄付金を基に建てられた。切妻造，亜鉛板葺で，正面にポーチを設けて入口とするほか，背面側で本館と廊下を介して接続している。過度に装飾を設けない簡素な外観が特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002734"},{"id":"00006962","register_sub_id":"101","register_pk":"107944","name":"星槎大学（旧頼城小学校）校舎","kana":"せいさだいがく（きゅうらいじょうしょうがっこう）こうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道芦別市緑泉町5-14他","lat":43.4594,"lng":142.166153,"geo_status":"db","era":"昭和29／31・32増築・平成15改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"煉瓦造一部鉄筋コンクリート造2階建、鉄板葺、建築面積2232㎡","structure_material":"煉瓦造一部鉄筋コンクリート造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"01 － 0095","desc":"煉瓦造２階建の学校建築である。西向きに玄関を開く職員室棟から東へ片廊下の北教室棟が延び、職員室棟の南にも片廊下の南教室棟が丁字形に接続する。屋根は寄棟造鉄板葺で、内・外壁とも煉瓦のイギリス積とする。１００ｍを超える長大な北教室棟は壮観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006962"},{"id":"00006770","register_sub_id":"101","register_pk":"107752","name":"星槎大学（旧頼城小学校）体育館","kana":"せいさだいがく（きゅうらいじょうしょうがっこう）たいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道芦別市緑泉町5-14他","lat":43.459724,"lng":142.166489,"geo_status":"db","era":"昭和29／平成15改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積757㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"01 － 0096","desc":"職員室棟の北に渡り廊下で接続する木造平屋建の東西棟。屋根は切妻造の鉄板葺である。外壁は腰を鎧下見板張、上部をモルタル塗とし、上下２段に窓を開く。内部は東端にステージと器具庫、西端に物入を設ける。２ヒンジ・トラスの木造小屋組に構造美を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006770"},{"id":"00001543","register_sub_id":"101","register_pk":"102533","name":"北海道教育大学函館校北方教育資料室（旧函館師範学校）","kana":"ほっかいどうきょういくだいがくはこだてこうほっぽうきょういくしりょうしつ（きゅうはこだてしはんがっこう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市八幡町1-2","lat":41.793823,"lng":140.740448,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積320㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0022","desc":"もと函館師範学校本館の中央部分を保存したもの。木造，２階建，下見板張で，正面中央に３階建のランタン付塔屋を建ち上げ，前面に切妻造の車寄を突出させる。全体骨格は明治調であるが，細部には大正期の簡略化された意匠が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001543"},{"id":"00001541","register_sub_id":"101","register_pk":"102531","name":"北海道大学旧札幌農学校昆虫及養蚕学教室","kana":"ほっかいどうだいがくきゅうさっぽろのうがっこうこんちゅうおよびようさんがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西8丁目","lat":43.0709984,"lng":141.34250468,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積397㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0020","desc":"旧札幌農学校キャンパス内の東南端に位置したⅠ字型平面を持つ木造平屋建の建物。漆喰塗大壁造で，上げ下げ硝子窓が左右対称に配される。ピラスターとペディメントで構成される正面中央部が，寄棟屋根の両翼部と対照的に正面性を強調する。設計は中條精一郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001541"},{"id":"00001649","register_sub_id":"101","register_pk":"102639","name":"北海道大学旧札幌農学校図書館書庫","kana":"ほっかいどうだいがくきゅうさっぽろのうがっこうとしょかんしょこ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西8丁目","lat":43.0711992,"lng":141.34174935,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造2階建、建築面積119㎡","structure_material":"煉瓦造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0025","desc":"中條精一郎により設計された札幌農学校新キャンパスの施設である図書館の書庫。煉瓦造２階建、切妻造の倉庫建築であるが、腰積に焼過煉瓦を用い、コーナーの要所に石を配し、妻の笠石をステップ状に積むなど細やかな造型的・構造的処理が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001649"},{"id":"00001542","register_sub_id":"101","register_pk":"102532","name":"北海道大学旧札幌農学校図書館読書室","kana":"ほっかいどうだいがくきゅうさっぽろのうがっこうとしょかんどくしょしつ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西8丁目","lat":43.07104109,"lng":141.34180213,"geo_status":"db","era":"明治35／昭和27増築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積467㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0021","desc":"Ｔ字型平面を持つ木造平屋建の図書館閲覧棟。手前に張り出す棟には，２つの頂塔が載り，側面には三角・櫛形ペディメント付きの窓が交互に配置される。現キャンパスに移転した時のもので，旧昆虫及養蚕学教室とともに現位置に遺る。中條精一郎の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001542"},{"id":"00001544","register_sub_id":"101","register_pk":"102534","name":"北海道大学農学部附属苫小牧地方演習林森林記念館（旧標本貯蔵室）","kana":"ほっかいどうだいがくのうがくぶふぞくとまこまいちほうえんしゅうりんしんりんきねんかん（きゅうひょうほんちょぞうしつ）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道苫小牧市字高丘無番地","lat":42.67712887,"lng":141.59763375,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0023","desc":"苫小牧演習林のもと標本貯蔵室。木造平屋建，バットレス付下見板張，切妻造の教会堂風建築の背後に，駒形屋根の牧畜舎風建築を配する。屋根窓の３連の連続窓や，側面バットレス間の横長窓などに時代的な特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001544"},{"id":"00001540","register_sub_id":"101","register_pk":"102530","name":"北海道大学附属植物園庁舎（旧札幌農学校動植物学教室）","kana":"ほっかいどうだいがくふぞくしょくぶつえんちょうしゃ（きゅうさっぽろのうがっこうどうしょくぶつがくきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市中央区北3条西8丁目","lat":43.06394736,"lng":141.34428132,"geo_status":"db","era":"明治34／昭和17移築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積132㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0019","desc":"旧札幌農学校キャンパス内にあったⅠ字型平面からなる動植物講堂の東翼部を移築したもの。木造２階建，漆喰塗大壁。入口はピラスターとモディリオンに支えられた三角ペディメントで飾られる。当時文部省建築掛札幌出張所長の中條精一郎による設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001540"},{"id":"00000282","register_sub_id":"101","register_pk":"101272","name":"北海道大学古河記念講堂（旧東北帝国大学農科大学林学科教室）","kana":"ほっかいどうだいがくふるかわきねんこうどう（きゅうとうほくていこくだいがくのうかだいがくりんがくかきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西7","lat":43.07126814,"lng":141.34359488,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積414㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"01 － 0003","desc":"中央に入口を設け，左右に翼部を伸ばすルネッサンス様式の建築である。設計は文部省技師の新山平四郎。総２階建で，マンサード屋根をかけ，中央部にかつては時鐘が取りつけられていた小塔が設けられており，全体に簡素ではあるがまとまった意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000282"},{"id":"00001222","register_sub_id":"101","register_pk":"102212","name":"北上市立博物館付属民俗資料館（旧黒沢尻実科高等女学校校舎）","kana":"きたかみしりつはくぶつかんふぞくみんぞくしりょうかん（きゅうくろさわじりじつかこうとうじょがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県北上市立花14地割52","lat":39.269711,"lng":141.129776,"geo_status":"db","era":"昭和2／昭和52移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造２階建，スレート葺，建築面積456㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0020","desc":"木造２階建、切妻屋根の学校建築。外装の基調は白色下見板貼で、階上階下の腰を竪羽目とし、階上中央部を黒色ドイツ壁とする。昭和期の竣工であるが、端部妻のハンマービーム風の収まり、開口部のペジメントなどに明治建築の面影を色濃く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001222"},{"id":"00012086","register_sub_id":"101","register_pk":"352885","name":"旧上有住小学校校舎","kana":"きゅうかみありすしょうがっこう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県気仙郡住田町上有住字山脈地15-1","lat":39.197775,"lng":141.588165,"geo_status":"db","era":"昭和3年／昭和59年曳家・同60年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積459㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"03-106","desc":"昭和初期の小学校校舎。木造二階建、桟瓦葺で、正面中央部のみ鉄板葺とする。外壁は下見板張で、上部はドイツ壁とし、柱型を塗り分けて強調する洋風意匠でまとめている。中心にポーチを配して左右に延びる対称性の強い構成で、木造小学校校舎の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012086"},{"id":"00013917","register_sub_id":"101","register_pk":"508177","name":"旧制第二高等学校正門","kana":"きゅうせいだいにこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25244722,"lng":140.87287778,"geo_status":"db","era":"明治22年頃／昭和11年・同20年・同25年・同43年、平成8年移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"煉瓦造、間口4.4m、両脇門柱付","structure_material":"煉瓦造","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0205","desc":"東北大学正門から南約一〇〇メートルに所在する門。旧制第二高等学校校舎と共に設計。化粧煉瓦積角柱の上部に四角錐の笠石を載せる、間口四・四メートルの門柱二基。同形で一回り小さい脇門柱二基が立つ。移転を重ねたが、当初位置近くに旧観を取り戻した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013917"},{"id":"00011844","register_sub_id":"101","register_pk":"211033","name":"旧仙台医学専門学校博物・理化学教室（東北大学本部棟３）","kana":"きゅうせんだいいがくせんもんがっこうはくぶつ・りかがくきょうしつ（とうほくだいがくほんぶとう３）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.254366,"lng":140.873492,"geo_status":"db","era":"明治37年／大正13年頃・昭和2年頃・同10年頃・同中期・平成17年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺一部鋼板葺、建築面積504㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"04-139","desc":"東北大学片平キャンパス内に所在する。木造平屋建、寄棟造、瓦葺一部銅板葺で、北を正面とする東西棟と、その東に接続する南北棟部分からなる。外壁は下見板張。内部は北側に片廊下を通し、南側に諸室を配す。キャンパス草創期の景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011844"},{"id":"00011845","register_sub_id":"101","register_pk":"211034","name":"旧仙台医学専門学校六号教室（東北大学魯迅の階段教室）","kana":"きゅうせんだいいがくせんもんがっこうろくごうきょうしつ（とうほくだいがくろじんのかいだんきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.254155,"lng":140.873398,"geo_status":"db","era":"明治37年／大正13年頃・昭和10年頃移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"04-140","desc":"当初博物・理化学教室の東側に接して建っていたものが、二度の移築を経て向きを変え現在地に建っているもの。木造平屋建、桟瓦葺で、西を寄棟造、東を切妻造とする。内部は一室の階段教室とし、東側に講壇を設ける。明治期に遡る木造高等教育施設の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011845"},{"id":"00013915","register_sub_id":"101","register_pk":"508175","name":"旧仙台高等工業学校建築学科棟","kana":"きゅうせんだいこうとうこうぎょうがっこうけんちくがっかとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-3","lat":38.25039444,"lng":140.87631111,"geo_status":"db","era":"昭和5年／平成26年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積480㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0203","desc":"鉄筋コンクリート造三階建。スクラッチタイル貼に横長の連続窓を開け、壁面を張出すバウハウスに連なる外観。階段室は階段勾配に沿ってアーチ窓を開く。ヴォールトの通路を通し、アーチにＳＫＫの学章を付す。内部は片廊下式。前衛的な意匠が印象的な校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013915"},{"id":"00011846","register_sub_id":"101","register_pk":"211035","name":"旧第二高等学校書庫（東北大学文化財収蔵庫）","kana":"きゅうだいにこうとうがっこうしょこ（とうほくだいがくぶんかざいしゅうぞうこ）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.253001,"lng":140.874232,"geo_status":"db","era":"明治43年／平成24年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造3階建、瓦葺、建築面積83㎡","structure_material":"煉瓦造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-141","desc":"片平キャンパスの中程に建つ。煉瓦造三階建、寄棟造桟瓦葺。基礎部と各階腰部に褐色の煉瓦を水平に廻し、軒にはデンティルをつけ、四隅及び側背面の壁体中間に付柱を張出す。内部床組は木造独立柱で支える。当時書庫が重視されていたことを示す、煉瓦造の書庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011846"},{"id":"00005820","register_sub_id":"101","register_pk":"106807","name":"旧月立小学校校舎","kana":"きゅうつきだてしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市塚沢72","lat":38.95229302,"lng":141.5194695,"geo_status":"db","era":"大正11年／昭和16年増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積573㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"04 － 0063","desc":"校庭北部に建つ，横一文字型，北廊下式の校舎。建築面積５７３㎡，木造２階建，東端は寄棟造，西端は切妻造，桟瓦葺。正面中央に玄関ポーチ，屋根には大きな切妻破風を設けて特徴付け，外観をスティックスタイルとする。県内でも数少ない木造校舎建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005820"},{"id":"00013913","register_sub_id":"101","register_pk":"508173","name":"旧東北帝国大学工学部機械学及び電気学教室","kana":"きゅうとうほくていこくだいがくこうがくぶきかいがくおよびでんきがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25321111,"lng":140.87585,"geo_status":"db","era":"昭和5年／平成19年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積1，662㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0201","desc":"鉄筋コンクリート造地上三階地下一階建のＬ字型平面中廊下式校舎で階段ホール吹抜とする。外壁は上層をリシン仕上、下層を煉瓦タイル貼に塗装吹付とする。正面中央は玄関を突出させアーチを付し、外壁を石張として塔屋を掲げ、装飾を集中させて意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013913"},{"id":"00013914","register_sub_id":"101","register_pk":"508174","name":"旧東北帝国大学工学部機械学及び電気学実験室","kana":"きゅうとうほくていこくだいがくこうがくぶきかいがくおよびでんきがくじっけんしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25276389,"lng":140.8757,"geo_status":"db","era":"昭和4年／平成25年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積397㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0202","desc":"鉄筋コンクリート造二階建の校舎で矩形平面中廊下式で教室を並べる。外壁は一階は煉瓦タイル貼にアーチ窓を並べ、二階はリシン仕上に矩形窓を並べる。ステンドグラスを掲げた玄関と階段を中央に配する。教室校舎と同様上下二層の色使いが目立ち意匠平明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013914"},{"id":"00013918","register_sub_id":"101","register_pk":"508178","name":"旧東北帝国大学正門（東北大学正門）","kana":"きゅうとうほくていこくだいがくせいもん（とうほくだいがくせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25304722,"lng":140.87216111,"geo_status":"db","era":"大正15年／昭和40年代改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、間口6.3m、両脇門柱付","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0206","desc":"東北大学片平キャンパス西面に所在する門。鉄筋コンクリート造御影石張の角柱に、ペン先状の三角形の柱頭を載せ前後に柱形を付す。間口六・三メートルの門柱二基、同形式で縮小した脇柱を両脇に立てる。南本柱に東北大学の門標を付し、帝大の景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013918"},{"id":"00011847","register_sub_id":"101","register_pk":"211036","name":"旧東北帝国大学附属図書館閲覧室（東北大学史料館）","kana":"きゅうとうほくていこくだいがくふぞくとしょかんえつらんしつ（とうほくだいがくしりょうかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.253475,"lng":140.873349,"geo_status":"db","era":"大正15年／昭和61年・平成25年・同26年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階一部地下1階及び3階建、瓦葺、建築面積569㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部地下1階及び3階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-142","desc":"鉄筋コンクリート造で、北面中央に玄関を開き、一階に事務室等を配し、二階は大空間の閲覧室とする。外壁は腰部石張、一階化粧煉瓦張、二階は漆喰塗とし、一階窓はセグメンタルアーチ、二階窓は半円アーチでまとめる。ロマネスク風の意匠でまとめる図書館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011847"},{"id":"00013912","register_sub_id":"101","register_pk":"508172","name":"旧東北帝国大学法文学部第二研究室","kana":"きゅうとうほくていこくだいがくほうぶんがくぶだいにけんきゅうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25313889,"lng":140.87343611,"geo_status":"db","era":"昭和2年／平成16年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積374㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0200","desc":"鉄筋コンクリート造三階建。正面中央を張出して玄関を設け、頂部に切妻破風を掲げ、アーチ窓、矩形窓を縦に並べ間に煉瓦タイルを矢筈に貼る。外壁は吹付仕上で二連の矩形窓を並べる。内部は中廊下式。窓枠を煉瓦で縁取るなどアクセントを付けた愛らしい校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013912"},{"id":"00011848","register_sub_id":"101","register_pk":"211037","name":"旧東北帝国大学理学部化学教室棟（東北大学本部棟１）","kana":"きゅうとうほくていこくだいがくりがくぶかがくきょうしつとう（とうほくだいがくほんぶとう１）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.254126,"lng":140.87364,"geo_status":"db","era":"昭和7年／昭和10年増築、平成15年・同25年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積871㎡","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-143","desc":"鉄筋コンクリート造三階建で、背面側を廊下として正面側に諸室を配する。外壁は正面側を中心にスクラッチタイル貼とし、柱形を強調するなど垂直性の強いデザインが特徴で、特に中央玄関廻りは柱形を石張として荘重な外観を見せる。昭和初期の大学校舎の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011848"},{"id":"00013911","register_sub_id":"101","register_pk":"508171","name":"旧東北帝国大学理学部生物学教室","kana":"きゅうとうほくていこくだいがくりがくぶせいぶつがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-5","lat":38.25531111,"lng":140.86968333,"geo_status":"db","era":"大正13年／平成7年・令和元年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積668㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0199","desc":"鋭角な敷地にＶ字形平面を持つ鉄筋コンクリート造三階建校舎。腰を石積風モルタル塗、上部を煉瓦タイル貼とし縦長窓を並べる。Ｖ字の頂点は円筒形の壁を立上げる。平面は片廊下式で研究室、講義室等を配置。プロポーションと細部装飾にバランスが取れた逸品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013911"},{"id":"00013919","register_sub_id":"101","register_pk":"508179","name":"東北学院大学正門","kana":"とうほくがくいんだいがくせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区土樋一丁目1","lat":38.25011389,"lng":140.87726111,"geo_status":"db","era":"大正15年／昭和60年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、間口4.2m","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0207","desc":"校地北辺中央に位置。三角アーチの脇門二基を一対とした正門。鉄筋コンクリート造洗出に目地切りで石張にみせる。間口は四・二メートルで両開鉄扉を吊る。脇門はコーニスやデンティルで飾り、十字架にＴＧを重ねた校章を付す。歴史ある私学の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013919"},{"id":"00010246","register_sub_id":"101","register_pk":"199020","name":"東北学院大学大学院棟（旧シュネーダー記念東北学院図書館）","kana":"とうほくがくいんだいがくだいがくいんとう（きゅうしゅねーだーきねんとうほくがくいんとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和中","pref":"宮城県","address":"宮城県仙台市青葉区土樋1-1","lat":38.249943,"lng":140.877647,"geo_status":"db","era":"昭和28年／昭和38年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造5階建、瓦葺、建築面積613㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0096","desc":"当初は各面二二メートルの正方形で北西隅に玄関ホール、西半を吹抜けの閲覧室、東半を各階書庫とする。階高を抑えた鉄筋コンクリート造五階建であるが、縦長窓を巧妙に配して三階建風にまとめ、均整のとれた外観とする。本館北東に西面し、学院の核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010246"},{"id":"00010244","register_sub_id":"101","register_pk":"199018","name":"東北学院大学本館（旧東北学院専門部校舎）","kana":"とうほくがくいんだいがくほんかん（きゅうとうほくがくいんせんもんぶこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区土樋1-1","lat":38.249686,"lng":140.877262,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積647㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0094","desc":"学院中興期の建築になる鉄筋コンクリート造三階建。東西に細長い中廊下式平面で北面し、正面中央を塔屋状につくり玄関ポーチを構える。外観は地元産の秋保石を張り、いわゆるカレッジ・ゴシック様式で端正にまとめる。キャンパスの象徴的存在として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010244"},{"id":"00013916","register_sub_id":"101","register_pk":"508176","name":"本多記念館","kana":"ほんだきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-5","lat":38.25503889,"lng":140.8726,"geo_status":"db","era":"昭和16年／平成6年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積689㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0204","desc":"鉄筋コンクリート造地上三階地下一階建。柱形を強調したタイル貼の外壁に矩形窓を並べる。装飾的な要素はほぼ持たないが、玄関車寄から前方に張出す大キャノピーは目を引く。玄関ホールから楕円平面の階段室には大理石を張る。明快な意匠が時代相を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013916"},{"id":"00011849","register_sub_id":"101","register_pk":"211038","name":"南三陸町民俗資料館","kana":"みなみさんりくちょうみんぞくしりょうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県本吉郡南三陸町歌津字伊里前123","lat":38.719287,"lng":141.52292,"geo_status":"db","era":"大正12年／昭和26年移築、昭和32年増築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積411㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-144","desc":"伊里前小学校の校舎として建てられ、昭和二六年に移築されたもの。平屋部分は正面側に廊下を通し、背面側に教室を配する。南寄りの二階部は増築で、一階は調理室、二階は床棚を備えた大広間で、船底天井とする。作法室を備えるなど学校建築の特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011849"},{"id":"00010245","register_sub_id":"101","register_pk":"199019","name":"ラーハウザー記念東北学院礼拝堂","kana":"らーはうざーきねんとうほくがくいんれいはいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区土樋1-1","lat":38.249915,"lng":140.876876,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積619㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0095","desc":"南北に長い鉄筋コンクリート造建築で、南に玄関とホール、Ｔ字形の礼拝堂の北に教壇を構え、両脇とホール二階をバルコニーとする。扁平尖頭アーチの縦長窓や笠付の柱形が垂直性を強調するカレッジ・ゴシック様式の外観で、本館とともに学院の核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010245"},{"id":"00009118","register_sub_id":"101","register_pk":"164671","name":"旧鮎川小学校屋内運動場","kana":"きゅうあゆかわしょうがっこうおくないうんどうじょう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33411757,"lng":140.06590965,"geo_status":"db","era":"昭和28年／平成3年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積548㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"北校舎棟と、昇降口を介して接続する。東西棟の切妻造桟瓦葺で西面に下屋を付設。建築面積548平方メートル。内部は高く広い空間で、西面にステージなどを設け、平側に大きく開口を設けて外光を取込む。東妻の灰色壁面に高く延びる白い柱列が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009118"},{"id":"00009119","register_sub_id":"101","register_pk":"164672","name":"旧鮎川小学校北校舎棟","kana":"きゅうあゆかわしょうがっこうきたこうしゃとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33382311,"lng":140.06576093,"geo_status":"db","era":"昭和28年／昭和50年・平成3年・平成9年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積571㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"屋内運動場と中央校舎棟の間に東西棟で建ち、切妻造桟瓦葺、平屋建である。北側廊下で、東端に図書館、西端に音楽室、その間に普通教室を並べる。教室北面は両端を出入口とし、その間は腰板壁と引違窓とする。長廊下に木製建具が連続し、穏やかな空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009119"},{"id":"00009120","register_sub_id":"101","register_pk":"164673","name":"旧鮎川小学校中央校舎棟","kana":"きゅうあゆかわしょうがっこうちゅうおうこうしゃとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33362383,"lng":140.06585908,"geo_status":"db","era":"昭和28年／平成3年・平成9年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積649㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"校地の西寄りに建ち並ぶ校舎の中央に位置する。東西に長い切妻造桟瓦葺、建築面積649平方メートル。東面北側に玄関を設け、昇降口と渡廊下で南校舎棟と繋ぐ。北側を廊下とし、東から校長室や職員室、特別教室等を並べる。下見板張の外観が安らぎを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009120"},{"id":"00009121","register_sub_id":"101","register_pk":"164674","name":"旧鮎川小学校南校舎棟","kana":"きゅうあゆかわしょうがっこうみなみこうしゃとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33340968,"lng":140.06597211,"geo_status":"db","era":"昭和29年／平成3年・平成9年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積651㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"中央校舎棟を中心に、北校舎棟と対称位置に建つ。北面の昇降口と渡廊下で中央棟と接続し、左右対称の整然とした立面をもつ。小屋はキングポストトラス。教室の配置計画や構造など当時の状況を伝えるとともに、木の温もりを感じさせる良質な学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009121"},{"id":"00002348","register_sub_id":"101","register_pk":"103338","name":"旧男鹿市立加茂青砂小学校屋内体操場","kana":"きゅうおがしりつかもあおさしょうがっこうおくないたいそうじょう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"秋田県","address":"秋田県男鹿市戸賀加茂青砂字山道添38","lat":39.90926459,"lng":139.73272938,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"05 － 0073","desc":"校舎の北西に接続して建つ。木造平屋建，切妻造，鉄板葺で，南東正面にもと校舎にあった玄関が移設されて取り付いている。外観は一部改められているが，内部は，梁間約１１ｍに及ぶキングポストトラスにより，柱を立てない大空間を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002348"},{"id":"00002347","register_sub_id":"101","register_pk":"103337","name":"旧男鹿市立加茂青砂小学校校舎","kana":"きゅうおがしりつかもあおさしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県男鹿市戸賀加茂青砂字山道添38","lat":39.909176,"lng":139.733002,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積299㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"05 － 0072","desc":"木造２階建，寄棟造，鉄板葺で，正面中央に切妻造の玄関，背面中央に下屋を設ける。１，２階とも背面側に廊下を配し，正面側に教室や職員室を並べる。下見板張りと大きく開いた連続窓によって構成される明快な外観は，集落の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002347"},{"id":"00009893","register_sub_id":"101","register_pk":"196040","name":"桜丘会館","kana":"おうきゅうかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県いわき市平字桜町5-1","lat":37.06238111,"lng":140.88715945,"geo_status":"db","era":"昭和13／昭和27改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"07 － 0148","desc":"敷地南に位置する旧磐城高等女学校の図書館兼同窓会館。一階を図書館、二階を畳敷の教室とする本館と、西の生徒生活実習寮である新館からなる。モルタル塗の外壁に丸窓や欠円アーチの縦長窓、隅部に横長窓を付すなど、昭和前期における建築潮流の影響を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009893"},{"id":"00012279","register_sub_id":"101","register_pk":"531603","name":"旧福島県立相馬中学校講堂","kana":"きゅうふくしまけんりつそうまちゅうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県相馬市中村字大手先57-1","lat":37.79448056,"lng":140.91424722,"geo_status":"db","era":"昭和8年／昭和42年増築、平成28年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積530㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"07-184","desc":"現県立相馬高校の講堂。木造平屋建妻入で、正面に玄関を張出し、大屋根と玄関の大小二つの切妻屋根を重ね、窓廻りを幾何学模様の意匠で整える。外壁は下見板張で、腰に人造石を横使いで張り、水平性を強調する。旧制中学校構内の構成を伝える学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012279"},{"id":"00007445","register_sub_id":"101","register_pk":"108427","name":"長井市立長井小学校第一校舎","kana":"ながいしりつながいしょうがっこうだいいちこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県長井市ままの上1764他","lat":38.10777931,"lng":140.04234062,"geo_status":"db","era":"昭和8／平成元改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1157㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"06 － 0111","desc":"市役所に隣接する敷地に建つ。桁行９３ｍ梁間１１ｍ規模で、切妻造桟瓦葺とする東西に長い木造総２階建の学校建築。切妻造妻入の正面玄関を中心とする左右対称の外観とし、階段など内部の造作もよく残す。スティックスタイルによる丁寧なつくりの木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007445"},{"id":"00002501","register_sub_id":"101","register_pk":"103491","name":"山形市立第一小学校校舎","kana":"やまがたしりつだいいちしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市本町1-5-19","lat":38.25061945,"lng":140.33596872,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1483㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0037","desc":"山形県初の鉄筋コンクリート造３階建の校舎。コの字型の左右対称の平面で，正面となる北面中央を４階建に相当する塔屋とし，１階に玄関ポーチを設ける。簡明な外観であるが，随所に表現主義やアールデコの細部をあしらい，校舎の風格をつくり出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002501"},{"id":"00002502","register_sub_id":"101","register_pk":"103492","name":"山形市立第一小学校門柱及び柵","kana":"やまがたしりつだいいちしょうがっこうもんちゅうおよびさく","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市本町1-5-19","lat":38.25061307,"lng":140.33640708,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造、柵折曲り延長100m","structure_material":"鉄筋コンクリート造","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0038","desc":"校舎の正面にある。敷地の北側を画し，中央に門柱２基が建ち，その東西に長さ約１００ｍの塀が延びる。方形の門柱は高さ約２．６ｍで上部飾りをつけ，塀は腰から立ち上げた柱を鋼管で結ぶ形式。簡素なものであるが，要所にアールデコ等の細部を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002502"},{"id":"00000119","register_sub_id":"101","register_pk":"101109","name":"米沢女子高等学校校舎","kana":"よねざわじょしこうとうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県米沢市門東町1-1-72","lat":37.9078408,"lng":140.10980572,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1713㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"06 － 0004","desc":"総二階建Ｌ型平面になる校舎で，中央部に垂直線を強調した素朴な意匠の玄関を設ける。外壁は下見板張りのハーフティンバーとし，２階窓枠の下に気抜きの小窓等を設けてアクセントとする。昭和初期の学校建築の好例で，風格のある外観は市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000119"},{"id":"00000561","register_sub_id":"101","register_pk":"101551","name":"宇都宮高校旧本館","kana":"うつのみやこうこうきゅうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県宇都宮市滝の原3-5-70","lat":36.54020125,"lng":139.86429524,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造２階建，瓦葺，建築面積684㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0003","desc":"寄棟造の大屋根を架けた県内最古の学校建築。１階は事務室・職員室・校長室など，２階は広い１室の講堂で，木材は日光杉並木の杉材を用いている。全国中学校建築のモデルになるとともに，「白亜館」の名で卒業生のみならず多くの市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000561"},{"id":"00011632","register_sub_id":"101","register_pk":"210648","name":"宇都宮大学峰ヶ丘講堂（旧宇都宮高等農林学校講堂）","kana":"うつのみやだいがくみねがおかこうどう（きゅううつのみやこうとうのうりんがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市峰町350","lat":36.550853,"lng":139.911914,"geo_status":"db","era":"大正13年／平成21年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積384㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"09-0234","desc":"大学構内の北西に北面して建つ講堂。切妻造桟瓦葺妻入で外壁は柱形付下見板張とする。内部は正面に演台を据え側背面にギャラリーを廻らす。直線を強調した平坦な壁面や柱頭飾、天井の緩やかな円弧状アーチ飾りなど、セセッション的意匠で全体をまとめた優作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011632"},{"id":"00003056","register_sub_id":"101","register_pk":"104046","name":"宇都宮白楊高校旧講堂","kana":"うつのみやはくようこうこうきゅうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市今泉町2021","lat":36.56449248,"lng":139.91151897,"geo_status":"db","era":"明治36／昭和24・41移築","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"09 － 0061","desc":"宇都宮駅東側に建設された旧栃木県立農学校の施設。木造平屋建，寄棟造，瓦葺で外装下見板張。背面に物置を張出し，各側面に６つの上げ下げ窓を密に配する。全体的に簡素ながら丁寧な造りで，折上げ支輪，竿縁天井など和風を意識した意匠を随所に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003056"},{"id":"00003057","register_sub_id":"101","register_pk":"104047","name":"宇都宮白楊高校正門","kana":"うつのみやはくようこうこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市今泉町2021","lat":36.562714,"lng":139.9104,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造、間口3.6m、左右通用門付","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"09 － 0062","desc":"構内の南端に位置する。３．６ｍ間隔で配された高さ２．７５ｍの石造門柱の左右に，高さ２．５ｍの石造門柱を設置し，通用門とする。石材はいずれも花崗岩江戸切り仕上げで，雨仕舞を考慮し頂部を錐形とする。往時の学舎の姿を知る上で欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003057"},{"id":"00011262","register_sub_id":"101","register_pk":"209098","name":"旧粟野中学校校舎","kana":"きゅうあわのちゅうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"栃木県","address":"栃木県鹿沼市口粟野1812","lat":36.523269,"lng":139.669034,"geo_status":"db","era":"昭和24／昭和35増築","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積755㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0230","desc":"木造二階建、桁行七三メートルの長大な中学校校舎。片廊下式の平面で、地元の木材を使用し柱を抱合せ柱とするなど堅牢なつくりとする。外観は下見板張で木製ガラス窓を並べ、切妻造桟瓦葺屋根を載せる。保存状態も良く、林業で栄えた地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011262"},{"id":"00013505","register_sub_id":"101","register_pk":"504869","name":"旧木幡小学校校舎","kana":"きゅうきばたしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県芳賀郡茂木町大字木幡252","lat":36.5039,"lng":140.16263056,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積754㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"09 － 0256","desc":"平屋建切妻造桟瓦葺の小学校校舎。長大な矩形の平面を持ち、北に片廊下を通して南に教室六室及び職員室を並べる。南面に開口を大きくとり漆喰塗の小壁に菱形の飾りをつける。正面中ほどの腰折破風のハーフチンバーの玄関が印象的な戦前に遡る木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013505"},{"id":"00011265","register_sub_id":"101","register_pk":"209101","name":"旧本山小学校講堂","kana":"きゅうほんざんしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県日光市足尾町上間藤16-1","lat":36.657983,"lng":139.448058,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積308㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0233","desc":"上間藤市街地の松木川対岸の旧校地に建つ。切妻造平屋建の講堂で、校庭側の西を正面とする。正側面には縦長の窓を並べ、その間には木製バットレスを付す。妻壁は木骨を意匠的に配したハーフティンバー風の造りとする。足尾銅山の歴史を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011265"},{"id":"00001557","register_sub_id":"101","register_pk":"102547","name":"栃木高校記念館（旧栃木県尋常中学校栃木分校本館）","kana":"とちぎこうこうきねんかん（きゅうとちぎけんじんじょうちゅうがっこうとちぎぶんこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町12-4","lat":36.384098,"lng":139.730347,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積397㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"09 － 0024","desc":"栃木県尋常中学校栃木分校の本館として明治２９年に建設。木造２階建，寄棟造・桟瓦葺，外壁下見板張ペンキ塗とした全体に質素な形式であり，明治期の中学校建築の様相を示すが，階上には陸軍大演習時の明治・大正天皇の行在所が保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001557"},{"id":"00000563","register_sub_id":"101","register_pk":"101553","name":"栃木高校記念図書館","kana":"とちぎこうこうきねんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市入舟町12-4","lat":36.38315281,"lng":139.73091876,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，瓦葺，建築面積224㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0005","desc":"同窓会の記念事業として建てられ，１階が図書閲覧室，２階が和室の大広間になる。１階平面は凸型になり，玄関ポーチの装飾を巧みに強調している。当時の専用図書館として珍しいだけでなく，瀟洒ながら全体に均衡のとれた意匠を持つところに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000563"},{"id":"00000562","register_sub_id":"101","register_pk":"101552","name":"栃木高校講堂","kana":"とちぎこうこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町12-4","lat":36.38326063,"lng":139.73010651,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積409㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0004","desc":"木造平屋建の講堂建築。外観は上部半円型のルネッサンス風の窓が連続し，軒廻りの持送りや小壁の装飾と相俟って造形美のある意匠となっている。広い内部も，白漆喰の天井や飾り柱を備えた演壇廻りの本格的な細部意匠に，時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000562"},{"id":"00000564","register_sub_id":"101","register_pk":"101554","name":"真岡高校記念館","kana":"もおかこうこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県真岡市白布ヶ丘24-1","lat":36.44063381,"lng":139.99942247,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造２階建，瓦葺，建築面積744㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0006","desc":"入母屋造・総２階建の旧本館で，１階が事務室・職員室・校長室など，２階が広い講堂になる。下見板張りに上げ下げ窓という素朴な外観は，「質実剛健」の校風をよく示している。現在は校史を物語る施設として整備・活用が図られ，広く卒業生に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000564"},{"id":"00000122","register_sub_id":"101","register_pk":"101112","name":"真岡市久保講堂（旧真岡小学校久保講堂）","kana":"もおかしくぼこうどう（きゅうもおかしょうがっこうくぼこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県真岡市田町1345-1","lat":36.43848524,"lng":140.0175479,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建左右塔屋付，瓦葺，建築面積651㎡","structure_material":"木造2階建左右塔屋付","registered":"1997.05.07(平成9.05.07)","register_no":"09 － 0001","desc":"遠藤新設計の木造二階建の旧小学校講堂。内部は広い板敷で，２階にはギャラリーがある。水平線を強調した正面バルコニーの左右に塔屋を設けた意匠に特徴があり，遠藤新の作風がよく現れている。昭和６２年移築保存され市の文化施設として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000122"},{"id":"00000723","register_sub_id":"101","register_pk":"101713","name":"川場村歴史民俗資料館（旧川場尋常高等小学校校舎）","kana":"かわばむられきしみんぞくしりょうかん（きゅうかわばじんじょうこうとうしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県利根郡川場村大字天神1122","lat":36.69303174,"lng":139.10540245,"geo_status":"db","era":"明治43／昭和61移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積579㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"10 － 0027","desc":"木造下見板貼，瓦葺の典型的な小学校建築で，正面中央に車寄を付す。川場村は旧会津街道の宿場で，教育村としても知られている。この校舎はその象徴として村民に愛され親しまれており，昭和６１年現在地に移築され資料館として保存活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000723"},{"id":"00002509","register_sub_id":"101","register_pk":"103499","name":"旧東村花輪小学校校舎","kana":"きゅうあずまむらはなわしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県みどり市東町花輪191","lat":36.522396,"lng":139.309067,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積627㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0086","desc":"当地の出身で「日本の製鋼・鋼管技術の先駆者」とされる今泉嘉一郎の寄付により建設。木造２階建，切妻造，フランス瓦葺，下見板張の学校建築で，北面片廊下とし正面中央に玄関ポーチを突出させる。昇降口部の窓構成や腰折れ屋根窓などに造形的特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002509"},{"id":"00002510","register_sub_id":"101","register_pk":"103500","name":"旧東村花輪小学校門柱","kana":"きゅうあずまむらはなわしょうがっこうもんちゅう","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県みどり市東町花輪191","lat":36.521969,"lng":139.309494,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造、間口2.9m、高さ3.0m","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0087","desc":"門柱は高さ３ｍ，３０ｃｍ角ほどの花崗石製で，江戸切り状に仕上げる。左の門柱側面に「大正五年二月建之」とあり，前身校舎時代の建立を示す。平成５年頃，前面道路の拡幅に伴い，校庭よりも低い道路沿いの現在地に移設されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002510"},{"id":"00000948","register_sub_id":"101","register_pk":"132572","name":"旧桐生高等染織学校正門","kana":"きゅうきりゅうこうとうせんしょくがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市天神町1-5-1","lat":36.42282269,"lng":139.3471222,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造，鉄製門扉附属，高さ3.7m，幅16.8m","structure_material":"煉瓦造","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0032","desc":"旧桐生高等染織学校創立時の正門。本館の移設に応じて，本館玄関前の現位置に移設保存された。煉瓦造の門柱上部四面にゴシック風のポーチコを付けて頂部に門灯を掲げる。東京大学本郷キャンパスの煉瓦塀に似た門として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000948"},{"id":"00011634","register_sub_id":"101","register_pk":"210650","name":"群馬県立沼田高等学校屋内運動場（旧沼田中学校講堂）","kana":"ぐんまけんりつぬまたこうとうがっこうおくないうんどうじょう（きゅうぬまたちゅうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県沼田市西原新町1510","lat":36.646145,"lng":139.052839,"geo_status":"db","era":"昭和3年／平成27年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積380㎡","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"10-0338","desc":"管理教室棟の東に接して建つ。外観は管理教室棟と同じ簡素な仕上で、内部一階は武道場、二階は講堂であったが現在は屋内運動場となっている。鉄骨鉄筋コンクリート造で、二階床は水平、小屋組はアーチ状の鉄骨トラスを現し内部空間を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011634"},{"id":"00011633","register_sub_id":"101","register_pk":"210649","name":"群馬県立沼田高等学校管理教室棟（旧沼田中学校校舎）","kana":"ぐんまけんりつぬまたこうとうがっこうかんりきょうしつとう（きゅうぬまたちゅうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県沼田市西原新町1510","lat":36.646052,"lng":139.05215,"geo_status":"db","era":"昭和3年／平成24年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建一部地下1階建、建築面積921㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建一部地下1階建","registered":"2017.06.28(平成29.06.28)","register_no":"10-0337","desc":"敷地北寄りに北面して建つ校舎建築。外観は装飾を排した簡素で平坦な仕上とするが、玄関周りや階段ホールなどにアールデコ風の装飾が見られる。平面は片廊下式で教室を並べ中央に塔屋を付す。県内最初の鉄筋コンクリート造学校建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011633"},{"id":"00000947","register_sub_id":"101","register_pk":"101937","name":"群馬大学工学部守衛所（旧桐生高等染織学校門衛所）","kana":"ぐんまだいがくこうがくぶしゅえいじょ（きゅうきりゅうこうとうせんしょくがっこうもんえいじょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市天神町1-5-1","lat":36.42269403,"lng":139.34690777,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積18㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0031","desc":"桐生高等染織学校創立時の門衛所。木造平屋建，瓦葺切妻屋根，下見板張りで，本館と同系列の造りとし，規模に応じた簡略化を図っているが，下を三角に切り欠いた板を竪羽目にした妻面の意匠など相応の見所を造ることも忘れていない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000947"},{"id":"00000946","register_sub_id":"101","register_pk":"101936","name":"群馬大学工学部同窓記念会館（旧桐生高等染織学校本館・講堂）","kana":"ぐんまだいがくこうがくぶどうそうきねんかいかん（きゅうきりゅうこうとうせんしょくがっこうほんかん・こうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市天神町1-5-1","lat":36.42299129,"lng":139.34723166,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造２階建，便所棟附属，瓦葺，建築面積592㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0030","desc":"大正４年設置になる桐生高等染織学校の創立時の本館。正面玄関の奥に講堂を配置する。設計は，文部省大臣官房建築課桐生出張所長で文部技師の新山平四郎とされる。木造２階建，下見板張りで，ハンマービームを用いた妻飾りの意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000946"},{"id":"00010110","register_sub_id":"101","register_pk":"197943","name":"玉村八幡宮末社国魂神社（旧玉村尋常高等小学校奉安殿）","kana":"たまむらはちまんぐうまっしゃくにたまじんじゃ（きゅうたまむらじんじょうこうとうしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県佐波郡玉村町大字下新田字八幡1","lat":36.305016,"lng":139.108594,"geo_status":"db","era":"明治43／昭和21移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.0㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0319","desc":"拝殿の西に建つ。旧玉村尋常高等小学校の奉安殿で、戦後移築され国魂神社とされた。神社建築を範とした切妻造平入、銅板葺の建物で、壁面全面を鉄板張とする。かつては棟に千木と堅魚木、破風の拝みに鞭掛がついていた。明治期に遡る木造奉安殿の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010110"},{"id":"00008416","register_sub_id":"101","register_pk":"134812","name":"富岡市講堂（旧富岡尋常高等小学校講堂）","kana":"とみおかしこうどう（きゅうとみおかじんじょうこうとうしょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市富岡1753-1","lat":36.25871076,"lng":138.89359466,"geo_status":"db","era":"昭和8年／昭和26年・昭和52年・平成3年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積909㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"10 － 0303","desc":"富岡小学校敷地の西側に南面して建つ。木造平屋建。正面の玄関ポーチと、その奥の半切妻造桟瓦葺の講堂からなる。建築面積九〇九平方メートル。南正面はアーチを連続させた開口部や、レリーフにより左右対称の洋風の構成をみせ、堂々として風格を感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008416"},{"id":"00012292","register_sub_id":"101","register_pk":"531616","name":"新島学園短期大学研究棟（旧高崎市立女子高等学校円形校舎）","kana":"にいじまがくえんたんきだいがくけんきゅうとう（きゅうたかさきしりつじょしこうとうがっこうえんけいこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県高崎市昭和町84-1他","lat":36.33707778,"lng":139.00504167,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積491㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2018.05.10(平成30.05.10)","register_no":"10-340","desc":"もと高崎市立女子高等学校の円形校舎。鉄筋コンクリート造三階建で、円筒形の塔屋を付ける。各階の中央部は中心に螺旋階段を置くホールで、外周を六分割し教室五室と階段・便所を配する。坂本鹿名夫の初期の作で地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012292"},{"id":"00013226","register_sub_id":"101","register_pk":"366215","name":"旧埼玉県立松山中学校校舎（埼玉県立松山高等学校記念館）","kana":"きゅうさいたまけんりつまつやまちゅうがっこうこうしゃ（さいたまけんりつまつやまこうとうがっこうきねんかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県東松山市松山町一丁目1041他","lat":36.04484167,"lng":139.39645,"geo_status":"db","era":"大正12年／昭和45年移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、金属板葺、建築面積324㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0192","desc":"敷地西寄りに東面して建つ。外壁は下見板張、縦長の上下窓を規則的に配す。ドーマー等で屋根を装飾し、四面にペディメントを付した塔屋を中央に載せる。内部は中央に吹抜けの階段を配す。埼玉県内の旧制中学校の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013226"},{"id":"00001900","register_sub_id":"101","register_pk":"102890","name":"埼玉県立深谷商業高等学校記念館","kana":"さいたまけんりつふかやしょうぎょうこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県深谷市原郷80","lat":36.19700018,"lng":139.29130061,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積608㎡、塔屋付","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"11 － 0024","desc":"市中心部，国道17号線沿いに建つ学校建築。木造2階建，瓦葺，外装横板張で，意匠を凝らした塔屋・車寄付の中央部を軸に左右対称の外観構成をとる。4つの屋根窓，両翼端に櫛形ペディメントを設け，仏ルネサンス様式を基調とした高密度のデザインが施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001900"},{"id":"00007340","register_sub_id":"101","register_pk":"108322","name":"草加市立歴史民俗資料館（旧草加小学校西校舎）","kana":"そうかしりつれきしみんぞくしりょうかん（きゅうそうかしょうがっこうにしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県草加市住吉1-25-1","lat":35.832108,"lng":139.804291,"geo_status":"db","era":"大正15／昭和57改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積333㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"11 － 0123","desc":"道路に西面して建つＲＣ造２階建。外壁はモルタル仕上げで、柱型を現し、２連の縦長窓を開ける。パラペットの正・背面中央を山形に立ち上げる。西側に廊下、南北両端に階段室、各階に３教室を配し、屋上を運動場とする。県内最初期のＲＣ造の校舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007340"},{"id":"00013230","register_sub_id":"101","register_pk":"366219","name":"百間小学校すべり台","kana":"もんましょうがっこうすべりだい","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県南埼玉郡宮代町字西原261-1","lat":36.00886111,"lng":139.72727778,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、高さ3.1m、全長6.8m","structure_material":"鉄筋コンクリート造","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0196","desc":"校庭の南西隅に建つ。鉄筋コンクリート造で、柱脚上部の踊り場四隅に方形の支柱を立て、側面に枠を縁取った直線形の滑降部と階段を取り付ける。滑降面は人造石研出仕上とする。大正期に建設した鉄筋コンクリート造のすべり台として希少な現存例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013230"},{"id":"00015141","register_sub_id":"101","register_pk":"530565","name":"わらび幼稚園円形園舎","kana":"わらびようちえんえんけいえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県蕨市南町二丁目12-5","lat":35.81997778,"lng":139.69750833,"geo_status":"db","era":"昭和38年／平成9年改修","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積398㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"11 - 0231","desc":"蕨市の市街地南東に位置する幼稚園舎。鉄筋コンクリート造二階建の円形平面で北側に玄関を開き、一階は中央遊戯室の周りに扇形の保育室を配す。二階は一階より一回り小さく、外周を屋上テラスとする。狭隘敷地で採光を考慮した坂本鹿名夫による巧みな園舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015141"},{"id":"00000027","register_sub_id":"101","register_pk":"101017","name":"茨城県立水戸商業高等学校旧本館玄関","kana":"いばらぎけんりつみとしょうぎょうこうとうがっこうきゅうほんかんげんかん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県水戸市新荘３-７-２","lat":36.38717873,"lng":140.45454611,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積350㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"08 － 0001","desc":"明治36年に着工し翌年竣工した校舎の玄関部分。設計は茨城県技師駒杵勤治で，施工は大倉土木である。ベルサイユ宮殿を模したと伝え，屋根・柱の形態や石貼りの外壁にその特徴があらわれている。茨城県に多くの作品を残した駒杵勤治の模範的作品のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000027"},{"id":"00012288","register_sub_id":"101","register_pk":"531612","name":"旧浅川小学校一号棟","kana":"きゅうあさかわしょうがっこう１ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町浅川1253","lat":36.80136389,"lng":140.33406389,"geo_status":"db","era":"大正2年／昭和12年移築／昭和30年頃・平成9年・同18年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積362㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-311","desc":"桁行39メートルの長大な片廊下式の木造校舎。寄棟造桟瓦葺、外壁下見板張で、正面西寄りに切妻屋根の玄関を設ける。正面はガラス窓を二段に並べて教室の採光に配慮する。玄関奥の越屋根には時計を備える。谷あいにある集落の歴史的景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012288"},{"id":"00012289","register_sub_id":"101","register_pk":"531613","name":"旧浅川小学校二号棟","kana":"きゅうあさかわしょうがっこう２ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県久慈郡大子町浅川1253","lat":36.801125,"lng":140.3344,"geo_status":"db","era":"昭和12年／平成3年・同7年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積419㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-312","desc":"一号棟前方に矩折れに並んで建つ。一号棟と渡廊下で接続し、正面両端に簡易な昇降口を設ける。平屋建、切妻造の片廊下式で、一号棟とは広めの廊下や均質な教室配置など平面計画に違いがある。一号棟とともに、集落の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012289"},{"id":"00010257","register_sub_id":"101","register_pk":"199031","name":"旧上岡小学校第一棟","kana":"きゅううわおかしょうがっこうだいいちとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県久慈郡大子町大字上岡914他","lat":36.778189,"lng":140.327019,"geo_status":"db","era":"明治43年／大正15年・昭和43年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積373㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0263","desc":"東西棟の寄棟造鉄板葺で、校庭に南面する。中央に切妻造の玄関、東西両端に昇降口を設け、外壁は簓子下見板張、和小屋で一軒疎垂木である。平面は北側片廊下式で、玄関ホールを挟み東西各二室とする。改修はあるが、明治期木造校舎のかたちを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010257"},{"id":"00010259","register_sub_id":"101","register_pk":"199033","name":"旧上岡小学校第三棟","kana":"きゅううわおかしょうがっこうだいさんとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上岡946他","lat":36.778089,"lng":140.327447,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積236㎡、渡廊下及び便所付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0265","desc":"第一棟東に南面して建つ、切妻造鉄板葺の校舎。平面は北側片廊下式で教室二室及び旧図書室からなる。採光のために南面の高窓を大きくしながらも、軸部は主柱と添柱の二本組とし、上部に方杖を入れるなど構造強化を図っており、木造校舎の構法の進展を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010259"},{"id":"00010258","register_sub_id":"101","register_pk":"199032","name":"旧上岡小学校第二棟","kana":"きゅううわおかしょうがっこうだいにとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県久慈郡大子町大字上岡914他","lat":36.778374,"lng":140.327069,"geo_status":"db","era":"昭和12年／昭和38年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積326㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0264","desc":"第一棟の北側に並立し、廊下で接続する。桁行三一メートル、木造平屋建、切妻造鉄板葺で、小屋組はキングポストトラス、外壁は下見板張である。平面は講堂と多目的室の二室であるが、もとは北側片廊下式の四教室であった。昭和前期の学校拡充の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010258"},{"id":"00012281","register_sub_id":"101","register_pk":"531605","name":"旧岡田小学校女化分校校舎","kana":"きゅうおかだしょうがっこうおなばけぶんこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県牛久市女化町391-1","lat":35.94911944,"lng":140.17108333,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積388㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-304","desc":"旧校地の中央北寄りに南面して建つ。木造平屋建、外壁下見板張で、東寄りに切妻屋根の玄関を構える。片廊下式平面で北側を廊下とし、南側を大教室や中教室に仕切る。大教室は内部を二分でき、授業形態や多目的利用に対応する。市内現存唯一の戦前の木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012281"},{"id":"00004119","register_sub_id":"101","register_pk":"105109","name":"旧樺穂小学校校舎","kana":"きゅうかばほしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁351","lat":36.27767117,"lng":140.10165725,"geo_status":"db","era":"明治中期／大正期移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0133","desc":"桁行８間梁間３間規模，寄棟造，桟瓦葺の平屋建で，北面に半間幅の吹き放ち廊下を配し，中央東寄りに昇降口を張り出す。外観は押縁下見板張で，内部は中央で２室に分けていたものと見られる。旧長岡村の小学校校舎と推測されている。明治期学校建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004119"},{"id":"00010263","register_sub_id":"101","register_pk":"199037","name":"旧黒沢中学校屋内運動場","kana":"きゅうくろさわちゅうがっこうおくないうんどうじょう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2572-1他","lat":36.839197,"lng":140.348889,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄骨造平屋建一部地階付、鉄板葺、建築面積387㎡","structure_material":"鉄骨造平屋建一部地階付","registered":"2014.12.19(平成26.12.19)","register_no":"08-0269","desc":"本館北東に建つ切妻造の内部高大な施設で、西妻面にステージ部を張出し、南面東端にポーチ付出入口を設け、ステージ下に物置やシャワー室を備える。構造体の鉄骨は木部で覆い、大壁風のモルタル塗で、縦長窓と丸窓で外観を整えるなど、意匠面にも工夫がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010263"},{"id":"00010264","register_sub_id":"101","register_pk":"199038","name":"旧黒沢中学校音楽教室","kana":"きゅうくろさわちゅうがっこうおんがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2661-1他","lat":36.838605,"lng":140.347989,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積92㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0270","desc":"校地南のやや高い場所に建ち、本館南端二階と渡廊下で接続する。東西棟の切妻造桟瓦葺で、小屋組はトラス、外壁は下見板張である。内部は広い一室で、添柱や方杖を用いた軸部、広く高い開口部が特徴的である。本館と一体となり施設全体の正面を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010264"},{"id":"00010261","register_sub_id":"101","register_pk":"199035","name":"旧黒沢中学校技術教室","kana":"きゅうくろさわちゅうがっこうぎじゅつきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2600他","lat":36.839105,"lng":140.348225,"geo_status":"db","era":"昭和26年／昭和35年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0267","desc":"本館背面に独立し、棟を直交させて建つ切妻造鉄板葺で、外壁は下見板張、小屋組はトラス組と思われる。桁行七間梁間四間の広い一室が当初部で、南面東端に出入口を設け、板張の床に棹縁天井とする。本館と一連の建物で、初期中学校施設のあり様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010261"},{"id":"00010262","register_sub_id":"101","register_pk":"199036","name":"旧黒沢中学校調理室及び図書館","kana":"きゅうくろさわちゅうがっこうちょうりしつおよびとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2600他","lat":36.838976,"lng":140.348139,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0268","desc":"本館の中央背面に建つ。南を図書室、北を調理室とし、ともに桁行五間梁間四間の広い一室で、室境で調理室を後方にずらし、切妻造で鉄板葺屋根も棟違いとする。小屋組はキングポストトラス、外壁は下見板張、床を板張とし、棹縁天井を張る。本館と一連の施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010262"},{"id":"00010260","register_sub_id":"101","register_pk":"199034","name":"旧黒沢中学校本館","kana":"きゅうくろさわちゅうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2604他","lat":36.838926,"lng":140.348303,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積877㎡、渡廊下及び便所付","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0266","desc":"校庭に面して南東を向いて建つ。大規模な木造二階建で、小屋組はキングポストトラス、切妻造桟瓦葺とする。背面片廊下式で、正面中央に玄関、中央と両側に階段を設ける。外壁は下見板張で、添柱や方杖を用いた軸部、広い開口部など、初期中学校舎の一典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010260"},{"id":"00012285","register_sub_id":"101","register_pk":"531609","name":"旧西金小学校校舎","kana":"きゅうさいがねしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町西金250","lat":36.69701667,"lng":140.38688333,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階建、瓦葺、建築面積533㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"08-308","desc":"切妻造、南北棟の大規模な木造校舎。総二階建、外壁下見板張で、中央玄関部をモルタル塗として南北に分節する。内部は片廊下式で西側に通し、玄関部に防火扉を設けて二分する。大きな改変なく、発足間もない新制小学校の建築形式を伝える好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012285"},{"id":"00012287","register_sub_id":"101","register_pk":"531611","name":"旧西金小学校調理室","kana":"きゅうさいがねしょうがっこうちょうりしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町西金250","lat":36.69724167,"lng":140.38723611,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-310","desc":"校舎の正面側北隅に南面して建ち、矩折れの渡廊下で校舎と接続する。木造平屋建、切妻造桟瓦葺で、外壁を軒裏までモルタル塗とし、内部も天井をボード張とするなど内外に防火対策を講じる。音楽室･理科室と同じく、新制小学校最初期の構内の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012287"},{"id":"00012286","register_sub_id":"101","register_pk":"531610","name":"旧西金小学校理科室及び音楽室","kana":"きゅうさいがねしょうがっこうりかしつおよびおんがくしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町西金250","lat":36.69739722,"lng":140.38721389,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-309","desc":"校舎北側の高台に南面して建つ。南側に吹放ち下屋で外廊下を通し、その中央部を渡廊下で校舎二階と接続する。内部は東半を音楽室、西半を理科室とし、南北面ほとんどをガラス窓として採光を確保する。新制小学校最初期の構内の構成を伝える特別教室棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012286"},{"id":"00012282","register_sub_id":"101","register_pk":"531606","name":"旧初原小学校一号棟","kana":"きゅうはつばらしょうがっこう１ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県久慈郡大子町初原960","lat":36.81323889,"lng":140.30815556,"geo_status":"db","era":"昭和17年／昭和35年・平成2年改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積369㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-305","desc":"切妻造の東西棟、片廊下式の学校校舎。北側に廊下を通し、南面には教室の採光等に配慮し、ガラス窓上にガラス欄間を並べる。軸部･小屋組とも規格材を用い、トラスや添柱で効率的に構造耐力を確保するなど、戦時中の限られた用材で建てるための工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012282"},{"id":"00012283","register_sub_id":"101","register_pk":"531607","name":"旧初原小学校二号棟","kana":"きゅうはつばらしょうがっこう２ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町初原960","lat":36.81331944,"lng":140.30792222,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、金属板葺、建築面積100㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"08-306","desc":"一号棟西側に増築された木造二階建校舎で、上下階とも教室一室からなる。一号棟以上に教室の採光等を配慮し、南面のガラス窓上に大きなガラス欄間を並べ、構造耐力を確保するため、軸部を添柱や方杖で補強する。改造がほとんどなく建築当初の状態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012283"},{"id":"00012284","register_sub_id":"101","register_pk":"531608","name":"旧初原小学校講堂","kana":"きゅうはつばらしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町初原960","lat":36.81335556,"lng":140.30771389,"geo_status":"db","era":"昭和29年／昭和50年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-307","desc":"二号棟の北西方に渡廊下を延ばして接続する。木造平屋建、切妻造妻入で、外壁は軒裏までモルタル塗とし、ガラス窓を多用し採光を確保する。内部は一つの大空間で、天井を中央に向けて切上げて高くし、屋内運動場としても利用できるように工夫されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012284"},{"id":"00012290","register_sub_id":"101","register_pk":"531614","name":"旧槙野地小学校校舎","kana":"きゅうまきのちしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町槙野地2469","lat":36.8373,"lng":140.317775,"geo_status":"db","era":"昭和25年／昭和36年増築・平成10年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積553㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-313","desc":"桁行58メートルに及ぶ長大な木造校舎。内部が改変されているが、下見板張外壁の正面中央に切妻屋根の玄関、ガラス窓を二段に並べる外観は、当初の学校建築の形式をよく残している。地域の近代化を牽引した施設として、町民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012290"},{"id":"00003355","register_sub_id":"101","register_pk":"104345","name":"武道館（旧水海道小学校雨天体操場兼講堂）","kana":"ぶどうかん（きゅうみつかいどうしょうがっこううてんたいそうじょうけんこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県常総市水海道栄町2680-1","lat":36.01996362,"lng":139.98847207,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積541㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0077","desc":"小学校の雨天体操場兼講堂として建設されたが，現在は武道館として活用。木造平屋建，切妻造，スレート葺で，外壁は妻面破風と側面上部が真壁造，他は柱をあらわした下見板張にする。保存状態も良好で，端正で品格のある外観は，地域景観のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003355"},{"id":"00014321","register_sub_id":"101","register_pk":"511310","name":"旧公正會舘","kana":"きゅうこうせいかいかん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県銚子市新生町二丁目1-5","lat":35.73209167,"lng":140.83320278,"geo_status":"db","era":"大正15年／昭和後期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、建築面積524㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0318","desc":"市中心部に建つ鉄筋コンクリート造二階建で、夜間学校や図書館として建設された。二階は講堂で室内に映写室を張り出す。特に正面玄関廻りはセセッションを取り入れた円柱と垂直性の強い意匠で飾り立てる。地方都市で比較的早く鉄筋コンクリート造とした事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014321"},{"id":"00013510","register_sub_id":"101","register_pk":"504874","name":"旧佐倉市立志津小学校青菅分校校舎","kana":"きゅうさくらしりつしづしょうがっこうあおすげぶんこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県佐倉市青菅148","lat":35.74730833,"lng":140.15400278,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"12 － 0306","desc":"佐倉市の青菅地区に位置し、志津小学校分校として建築された。平屋建切妻造桟瓦葺。玄関脇に職員室を配し、片廊下を通してわずか二室の教室が配される小規模木造校舎。下見板張や木製の建具の使用など、戦後の建築ながら戦前からの木造校舎の意匠を引き継ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013510"},{"id":"00004875","register_sub_id":"101","register_pk":"105865","name":"千葉県立佐倉高等学校記念館","kana":"ちばけんりつさくらこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市鍋山町18","lat":35.723469,"lng":140.236816,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、銅板葺、建築面積691㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"12 － 0063","desc":"木造２階建の学校建築。正面ポーチに桜のレリーフを飾り，ドームを掲げた双塔，丸窓付の屋根窓，大棟の換気塔をスティック・スタイルでまとめる。建物端部にはハンマー・ビームの妻飾りがつく。外壁は柱形なしのドイツ下見板張。設計は久野節，後藤政次郎ら。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004875"},{"id":"00009435","register_sub_id":"101","register_pk":"194228","name":"千葉黎明学園生徒館","kana":"ちばれいめいがくえんせいとかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県八街市八街ほ628他","lat":35.66268651,"lng":140.30716342,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積303㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"12 － 0162","desc":"校地のほぼ中央に、木造平屋建の講堂兼武道場として建つ。半切妻屋根と屋根上のドーマー窓が特徴的であり、小屋組は木造変形トラスを組み、下弦をターンバックルで緊張させた独特な形式をもつ。八街市草創期の町の景観を直接伝える近代洋風建築物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009435"},{"id":"00013960","register_sub_id":"101","register_pk":"508220","name":"野田市立中央小学校旧正門","kana":"のだしりつちゅうおうしょうがっこうきゅうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東上町629","lat":35.94608333,"lng":139.86214722,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"石造及び煉瓦造、間口3.5m、左右袖塀及び石敷付","structure_material":"石造及び煉瓦造","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0313","desc":"敷地西方の流山街道に面して建ち、石畳を経て３年館昇降口に至る。間口三・五メートル開放の花崗岩門柱に、煉瓦造モルタル洗出仕上脇柱と色モルタル仕上袖塀を付設する。柱は断面方形で頂部に水勾配を取る。脇柱に控壁付き。歴史ある小学校の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013960"},{"id":"00013958","register_sub_id":"101","register_pk":"508218","name":"野田市立中央小学校３年館","kana":"のだしりつちゅうおうしょうがっこうさんねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字東上町619-1他","lat":35.94646111,"lng":139.86336389,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積836㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0311","desc":"桁行八三メートルに及ぶ長大な三階建校舎。一階外壁は横目地を入れ、三階まで柱形を立上げ柱頭に野田醤油の亀甲紋を象る。西面の昇降口に花輪飾等を付す。内部は片廊下式で一階は校長室等、二、三階は教室を配す。野田市初の鉄筋コンクリート造小学校校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013958"},{"id":"00013959","register_sub_id":"101","register_pk":"508219","name":"野田市立中央小学校７年館","kana":"のだしりつちゅうおうしょうがっこうしちねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字東上町611他","lat":35.94695,"lng":139.8638,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積864㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0312","desc":"敷地北面に位置する桁行九一メートルの鉄筋コンクリート造三階建校舎。外壁は一階から三階までドイツ壁風仕上で柱形を付し、南面は軒上に立ち上げ煙突を兼ねる。内部は東西端を昇降口とし片廊下式で教室を配す。３年館を踏襲しつつ細部意匠に違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013959"},{"id":"00007020","register_sub_id":"101","register_pk":"108002","name":"青山学院ベリーホール","kana":"あおやまがくいんべりーほーる","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都渋谷区渋谷4-22他","lat":35.66072331,"lng":139.71034935,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積817㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2008.04.18(平成20.04.18)","register_no":"13 － 0230","desc":"キャンパス中央ロータリーに西面して建つ。ＲＣ造３階建の主体部北端に平屋建の礼拝堂を設け、これと対称性を保って南端にも平屋建が付く。主体部や正面車寄はバットレスで飾り、欠円アーチや尖頭アーチ、簡明な細部彫刻を配す。ネオ・ゴシック風意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007020"},{"id":"00007019","register_sub_id":"101","register_pk":"108001","name":"青山学院間島記念館","kana":"あおやまがくいんまじまきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区渋谷4-22他","lat":35.660297,"lng":139.710175,"geo_status":"db","era":"昭和4／昭和30・51改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積208㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.04.18(平成20.04.18)","register_no":"13 － 0229","desc":"キャンパス中央ロータリーに北面して建つ。正面入口は基壇状に扱い、アーチ開口を設け、２階にコリント式円柱を並べてペディメントを掲げてローマ神殿を模す。両翼部は縦長窓で垂直性を強調し、上部コーニスをデンティルで飾る。ネオ・ルネサンス様式の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007019"},{"id":"00011895","register_sub_id":"101","register_pk":"211060","name":"井草幼稚園園舎","kana":"いぐさようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺一丁目155-2他","lat":35.713307,"lng":139.598665,"geo_status":"db","era":"昭和8年／昭和27年・同37年増改築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積324㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"13-392","desc":"講堂を中心としてＬ字型の平面を持ち、北寄りに住居部分を配する。園の創立者鈴木積善は浄土宗の僧侶であったが、寺院的意匠はほとんど見られない。小屋組はキングポストトラスで、外観は和風を基調とする。地域の歴史を今に伝える園舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011895"},{"id":"00014327","register_sub_id":"101","register_pk":"511316","name":"岡田日帰上人記念講堂","kana":"おかだにちきしょうにんきねんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区堀ノ内二丁目337-1他","lat":35.69108056,"lng":139.64725278,"geo_status":"db","era":"昭和12年／同15年・同後期・平成12年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下2階建、建築面積878㎡","structure_material":"鉄筋コンクリート造地上4階地下2階建","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0466","desc":"堀之内妙法寺西方にある立正高等女学校の講堂。鉄筋コンクリート造４階建、正面ピラスターで垂直性を強調、全体に装飾排し時代相を示すが、車寄せ廻りは当初テラゾ貼円柱で、八角窓やファンライトで荘厳する。講堂客席は緩傾斜で、２階席平面は円弧を描く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014327"},{"id":"00006805","register_sub_id":"101","register_pk":"107787","name":"お茶の水女子大学表門","kana":"おちゃのみずじょしだいがくおもてもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.7197039,"lng":139.7335399,"geo_status":"db","era":"昭和11／昭和30改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"門 鉄筋コンクリート造門柱2基、間口7.2m、左右通用門付 塀 鉄筋コンクリート造、総延長13m","structure_material":"門 鉄筋コンクリート造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0224","desc":"敷地北辺の中央、通りに面して建つ。門柱一対と左右の脇柱、鉄扉、塀からなり、鉄筋コンクリート造の表面に万成石を貼る。間口７．２ｍ、門柱の高さ４．１ｍ、塀の高さは３．２ｍである。幾何学的意匠を基調とし、当初の灯具や塀開口部のグリルなども良好に残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006805"},{"id":"00006804","register_sub_id":"101","register_pk":"107786","name":"お茶の水女子大学講堂","kana":"おちゃのみずじょしだいがくこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.718605,"lng":139.732376,"geo_status":"db","era":"昭和7／平成18改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積1018㎡","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0223","desc":"本館の中庭、中央玄関の奥に建つ。建築面積１，０１８㎡ 、鉄骨鉄筋コンクリート造、２階建。本館と同様、外壁を全面スクラッチタイル貼、腰壁を万成石貼として統一的意匠とするが、２階には２連アーチ窓を連続させて、より穏やかな外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006804"},{"id":"00006806","register_sub_id":"101","register_pk":"107788","name":"お茶の水女子大学附属幼稚園園舎","kana":"おちゃのみずじょしだいがくふぞくようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.718193,"lng":139.733063,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積1289㎡、砂場3ヶ所付","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0225","desc":"本館東側に位置する。園庭に東面する横長平面で、中廊下の両側に保育室などを配する。建築面積１，２８９㎡、鉄筋コンクリート造、平屋建。外壁はスクラッチタイル貼で、腰壁に万成石を貼る。保育室入口にステンドグラスをあしらうなど、洗練された意匠の園舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006806"},{"id":"00006803","register_sub_id":"101","register_pk":"107785","name":"お茶の水女子大学本館","kana":"おちゃのみずじょしだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.71879704,"lng":139.73254518,"geo_status":"db","era":"昭和7／平成15改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2990㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0222","desc":"コ字形平面で、建築面積２，９９０㎡ 、鉄筋コンクリート造、３階建、外壁をスクラッチタイル貼とする。正面中央の大庇付の玄関まわりでは、外壁を白色とし、植物紋様のレリーフを配するなど装飾を集中させる。内部に貴賓室も備える。震災復興校舎の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006803"},{"id":"00007619","register_sub_id":"101","register_pk":"108601","name":"学習院北別館（旧図書館）","kana":"がくしゅういんきたべっかん（きゅうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71950589,"lng":139.70937307,"geo_status":"db","era":"明治42／昭和53移築・平成9改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積393㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0240","desc":"校地の中央北寄りに建つ。東西２５ｍ南北２５ｍのＬ字形平面で、木造平屋建。急勾配の切妻造桟瓦葺とする。外壁はスティックスタイルとして柱間に下見板を張り、持送りや床下換気口は校章である桜花を模して飾る。木立の中、瀟洒で閑静な佇まいを醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007619"},{"id":"00007622","register_sub_id":"101","register_pk":"108604","name":"学習院厩舎","kana":"がくしゅういんきゅうしゃ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71688536,"lng":139.70847657,"geo_status":"db","era":"明治41／昭和2移築・昭和58改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積293㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0243","desc":"校地南面の馬場門脇に建つ。桁行２６ｍ梁間９．７ｍ、木造平屋建、寄棟造スレート葺で、西側に切妻造の馬具置場を併設する。腰高の鉄筋コンクリート基礎上に上屋を建て、横一列の採光窓を開け、壁は下見板を張る。都心に残る数少ない明治期建設の現役厩舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007622"},{"id":"00007623","register_sub_id":"101","register_pk":"108605","name":"学習院正門","kana":"がくしゅういんせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.7202149,"lng":139.709793,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"門 煉瓦造門柱4基、間口11m、左右通用門付、塀 石造、総延長36m","structure_material":"門 煉瓦造門柱4基","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0244","desc":"北面の目白通り沿いに開く間口１１ｍの正門で、左右に総延長３６ｍの石積塀を延ばし、生垣を植える。柱間６．３ｍの主柱に木製扉を吊り、その両側に脇柱を建てて脇門とする。門柱はいずれも煉瓦積で、頂部に花崗岩製の柱頭飾りを戴き、格調ある構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007623"},{"id":"00007618","register_sub_id":"101","register_pk":"108600","name":"学習院西一号館（旧中等科教場）","kana":"がくしゅういんにしいちごうかん（きゅうちゅうとうかきょうじょう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71833089,"lng":139.70800324,"geo_status":"db","era":"昭和5／昭和29増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下2階建、建築面積1366㎡","structure_material":"鉄筋コンクリート造3階一部地下2階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0239","desc":"南一号館の西側に矩折れに建つ。南北６６ｍ東西最長５０ｍ、鉄筋コンクリート造、地上３階一部地下２階建。南一号館と同様にネオゴシック様式を基調とした外観で、外壁をスクラッチタイル貼としており、並び建つ両館が重厚で格式のある一角を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007618"},{"id":"00007621","register_sub_id":"101","register_pk":"108603","name":"学習院乃木館（旧総寮部）","kana":"がくしゅういんのぎかん（きゅうそうりょうぶ）","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71793,"lng":139.707443,"geo_status":"db","era":"明治41／昭和19移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0242","desc":"西一号館の南隣に建つ。桁行１３ｍ梁間７．３ｍ、木造平屋建、寄棟造桟瓦葺で、外壁は下見板張である。東に廊下、西に３室を並べ、中央の十畳に院長乃木希典が起居していた。内部は真壁造で、棹縁天井を張る。洋風建築が多いキャンパスに、和風の佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007621"},{"id":"00007620","register_sub_id":"101","register_pk":"108602","name":"学習院東別館（旧皇族寮）","kana":"がくしゅういんひがしべっかん（きゅうこうぞくりょう）","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.719265,"lng":139.71002755,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積457㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0241","desc":"皇族のための別寮として計画されたもので、北別館の東側に並び建つ。並列する東西棟の建物２棟を繋ぐ形式で、東西３１ｍ南北２２ｍを測る。木造２階建、切妻及び寄棟造で桟瓦葺とする。北側に建ちの高い鋳鉄製の車寄を付設。大正初期の寄宿舎建築としても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007620"},{"id":"00007617","register_sub_id":"101","register_pk":"108599","name":"学習院南一号館（旧理科特別教場）","kana":"がくしゅういんみなみいちごうかん（きゅうりかとくべつきょうじょう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71779138,"lng":139.70850949,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積824㎡","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0238","desc":"校地の中央南寄りに建つ。鉄筋コンクリート造、地上３階一部地下１階建。東西５４ｍのＩ字形の対称形平面で、北面中央に石貼の玄関ポーチを構える。１階窓の尖塔アーチなど、垂直性を強調したネオゴシック様式の外観をもち、外壁にはスクラッチタイルを貼る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007617"},{"id":"00014462","register_sub_id":"101","register_pk":"512446","name":"国際基督教大学ディッフェンドルファー記念館","kana":"こくさいきりすときょうだいがくでぃっふぇんどるふぁーきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都三鷹市大沢三丁目1500-1","lat":35.68601389,"lng":139.52980556,"geo_status":"db","era":"昭和33年／平成12年・令和3年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1，175㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0478","desc":"国際基督教大学の校地内中央西寄りに建つ、講堂兼学生会館。設計はヴォーリズ建築事務所。北にオーディトリアムを有し、中央に広い中庭を設けた正方形平面で、広いガラス面、水平感の強調、初期のアルミサッシュなど戦後モダニズム建築の特徴を備えた秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014462"},{"id":"00016499","register_sub_id":"101","register_pk":"574861","name":"国際基督教大学本館","kana":"こくさいきりすときょうだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢三丁目1500-1他","lat":35.68168583,"lng":139.538495,"geo_status":"db","era":"昭和19年／昭和28年増築、同56年・平成15年改修","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積2，752㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0530","desc":"旧中島飛行機三鷹研究所設計本館を戦後に転用した大学校舎。キャンパス中心部に建つ鉄筋コンクリート造3階建で中央５スパンを４階建に増築し、正面性を強調。平面は各階中央ホールから左右に中廊下を延ばす。ヴォーリズ事務所改修による端正な外観の校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016499"},{"id":"00011888","register_sub_id":"101","register_pk":"211059","name":"国士舘大講堂","kana":"こくしかんだいこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都世田谷区世田谷四丁目28-1","lat":35.648315,"lng":139.653416,"geo_status":"db","era":"大正8年／昭和33年・同56年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-385","desc":"構内中央に建つシンボル的な大講堂。正面に入母屋造の大屋根妻面を見せ、妻飾の木連格子、舟肘木など伝統的な意匠を採る。内部はクイーンポストトラスにより一〇八畳の広間を造り、大床を備えた講壇や折上格天井の空間で威容を誇る創立期唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011888"},{"id":"00001566","register_sub_id":"101","register_pk":"102556","name":"渋谷区立広尾小学校","kana":"しぶやくりつひろおしょうがっこう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区東3-3-3","lat":35.651825,"lng":139.712143,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積940㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0081","desc":"高台に立つＲＣ造３階建で，関東大震災後の震災復興末期に建設。装飾は主に玄関廻りに用い，装飾を排したスタイルへの移行期の作風を示す。消防署が同居したことから火の見櫓としての塔屋を備える。設計は東京府の市ノ瀬仁重郎，施工は佐藤平治による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001566"},{"id":"00014460","register_sub_id":"101","register_pk":"512444","name":"墨田区立言問小学校校舎","kana":"すみだくりつことといしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都墨田区向島五丁目40","lat":35.71876111,"lng":139.81139722,"geo_status":"db","era":"昭和11年／平成23年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1，554㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0476","desc":"花柳街で栄えた向島にある小学校の現役の近代校舎。鉄筋コンクリート造三階建、大きな窓を並べる外観はいわゆるインターナショナルスタイル。階段から上下階廊下を見通す進歩的な造り。下町に所在するため校庭側に開放的で、街路側の1階昇降口を高窓とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014460"},{"id":"00014461","register_sub_id":"101","register_pk":"512445","name":"墨田区立言問小学校講堂","kana":"すみだくりつことといしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都墨田区向島五丁目40","lat":35.71878333,"lng":139.811725,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積508㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0477","desc":"向島北部にある小学校の現役の近代講堂。鉄骨造陸屋根、大空間を鉄骨トラスで確保する。震災復興の影響を見るリベット留めの太い鉄骨柱は壁の内側に立て、水平に窓を並べるインターナショナルスタイルの平明な外観。校舎と共に白亜の殿堂と呼ばれ親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014461"},{"id":"00002893","register_sub_id":"101","register_pk":"103883","name":"滝乃川学園本館","kana":"たきのがわがくえんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国立市谷保6312","lat":35.680962,"lng":139.42955,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"13 － 0133","desc":"木造総２階建，寄棟造・もとスレート葺で，玄関ポーチ付の中央部が一段高く，左右に両翼を延ばした形態とする。１階は中央廊下の前後に各室を配し，両端に階段室を設け，２階中央を講堂とする。胴蛇腹による水平線や整然と配した窓などに当時の造形が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002893"},{"id":"00009720","register_sub_id":"101","register_pk":"195549","name":"東京工業大学大岡山西一号館（旧分析化学実験室）","kana":"とうきょうこうぎょうだいがくおおおかやまにしいちごうかん（きゅうぶんせきかがくじっけんしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都目黒区大岡山2-1-1","lat":35.6053703,"lng":139.68291935,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階一部地下1階建、建築面積644㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部地下1階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0305","desc":"本館の北西側に東面する鉄筋コンクリート造二階建でＴ字形平面になる。外観はロマネスク風にまとめてスクラッチタイルを貼り、壁頂部に歯飾りを付す。正面中央には本館同様に石貼のポーチを構え、重厚さを醸す。灯具などの細部も良好に残る、風格ある復興校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009720"},{"id":"00009721","register_sub_id":"101","register_pk":"195550","name":"東京工業大学七〇周年記念講堂","kana":"とうきょうこうぎょうだいがくななじっしゅうねんきねんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都目黒区大岡山2-1-1","lat":35.6058914,"lng":139.68359035,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建一部地下2階付、建築面積1066㎡","structure_material":"鉄筋コンクリート造2階地下1階建一部地下2階付","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0306","desc":"本館前のキャンパス中心軸に東面して建つ。斜面地形を利用したホールを主体とした平面で、薄い軒を水平に差出し、中央にヴォールト屋根をかける。南側面には縦長のサッシを雁行させて独特な陰影をもつ窓割とし、テラコッタの装飾壁と共に豊かな表情を創り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009721"},{"id":"00009719","register_sub_id":"101","register_pk":"195548","name":"東京工業大学本館","kana":"とうきょうこうぎょうだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都目黒区大岡山2-1-1","lat":35.60443993,"lng":139.68386875,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階一部4階地下1階建、建築面積7063㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造3階一部4階地下1階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0304","desc":"大岡山キャンパスの中ほどに北面して建つ。主体部は鉄骨鉄筋コンクリート造三階建で、正面中央に塔屋や玄関ポーチを設ける。外壁は白いスクラッチタイル貼で、伊豆石貼のポーチに半円アーチを並べる。四方の立面を相称形に整え、本館としての威厳を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009719"},{"id":"00000388","register_sub_id":"101","register_pk":"101378","name":"東京商船大学１号館","kana":"とうきょうしょうせんだいがくいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66817421,"lng":139.79114384,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建，建築面積1769㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0003","desc":"関東大震災で多くの校舎が倒壊したが，昭和７年に再建。東京高等商船学校時代は，本館と呼ばれていた。外壁をスクラッチタイル貼りとし，正面に半円形の大アーチの玄関部を設ける。簡潔にまとめ上げられた意匠になる校舎の好例。設計は文部省・大蔵省。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000388"},{"id":"00000391","register_sub_id":"101","register_pk":"101381","name":"東京商船大学旧天体観測所（第一観測台）","kana":"とうきょうしょうせんだいがくきゅうてんたいかんそくじょ（だいいちかんそくだい）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66869347,"lng":139.79094413,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造2階建，鉄板葺，建築面積26㎡","structure_material":"煉瓦造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0006","desc":"正門の脇に建つ煉瓦造，２階建の観測台で，経緯儀室または赤道儀室が置かれた。一階は八角，二階は円形の平面をもち，二階外壁を漆喰塗りとしドーム屋根をかける。小規模ながら丁寧な造りの建物で，現存する数少ない明治期の天体観測施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000391"},{"id":"00000392","register_sub_id":"101","register_pk":"101382","name":"東京商船大学旧天体観測所（第二観測台）","kana":"とうきょうしょうせんだいがくきゅうてんたいかんそくじょ（だいにかんそくだい）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66885324,"lng":139.79111722,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造平屋建，鉄板葺，建築面積25㎡","structure_material":"煉瓦造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0007","desc":"第一観測台の脇に建つ煉瓦造，平屋建の小規模な観測台で，子午儀室が置かれた。平面は八角形で，屋根は八角錐，鉄板葺とする明治期の観測施設。壁面等に独特の観測用開口部を設ける。細部意匠は第一観測台と類似し，設計は両者とも三橋四郎と推定されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000392"},{"id":"00000390","register_sub_id":"101","register_pk":"101380","name":"東京商船大学事務局管理棟","kana":"とうきょうしょうせんだいがくじむきょくかんりとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66824078,"lng":139.79046482,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積400㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0005","desc":"１号館と同時に，図書館として再建されたものである。設計は文部省・大蔵省。外壁をスクラッチタイル貼とし，船をイメージした造形になるといわれ，細部の意匠も１号館と共通した構成要素がみられる。背後に円形の張り出し部をもつ構成は，特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000390"},{"id":"00000389","register_sub_id":"101","register_pk":"101379","name":"東京商船大学２号館","kana":"とうきょうしょうせんだいがくにごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66660314,"lng":139.79312766,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積2269㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0004","desc":"水産講習所本館として昭和８年に再建されたもので，設計は文部省・大蔵省。左右対称型の簡素な外観になる。外壁は，当時流行したスクラッチタイル貼とし，正面中央に４本の柱型を立て垂直性を強調した意匠とする。近年の改修で，性能向上が図られた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000389"},{"id":"00000647","register_sub_id":"101","register_pk":"101637","name":"東京女子大学講堂・礼拝堂","kana":"とうきょうじょしだいがくこうどう・れいはいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.70950127,"lng":139.59187469,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造２階建塔屋付，建築面積1186㎡","structure_material":"鉄筋コンクリート造２階建塔屋付","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0028","desc":"戦前期レーモンドの最後期の作品。担当は杉山雅則。塔とプレキャストのトレーサリーに特徴がある。オーギュスト・ペレのランシー教会堂をモデルとしたことで名高い。正門を入って右手に位置し，手前の礼拝堂部と奥の講堂部とから成る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000647"},{"id":"00000649","register_sub_id":"101","register_pk":"101639","name":"東京女子大学７号館（西校舎）","kana":"とうきょうじょしだいがくななごうかん（にしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71008246,"lng":139.59092274,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積806㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0030","desc":"本館の左手前に位置し，中庭を介して東校舎に向き合う。Ｅ字型平面で、玄関奥に講堂を張りだす。東校舎と同様な外観を呈するが，教室窓は東校舎よりも大きく，５連のスチールサッシをはめる。中央部の意匠は，ライト調がより濃厚である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000649"},{"id":"00000646","register_sub_id":"101","register_pk":"101636","name":"東京女子大学本館","kana":"とうきょうじょしだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71044319,"lng":139.59130352,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，一部瓦葺，建築面積1015㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0027","desc":"図書館として建設。レーモンドによる大正１０年のキャンパス計画に予定されており，着工は遅れて昭和期にずれこんだが，初期レーモンドの特徴であるライト調の面影を残す。校舎ゾーンの中心的建造物で，正門の突き当たりに位置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000646"},{"id":"00000648","register_sub_id":"101","register_pk":"101638","name":"東京女子大学６号館（東校舎）","kana":"とうきょうじょしだいがくろくごうかん（ひがしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71009248,"lng":139.59174442,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上２階建，瓦葺，建築面積1453㎡","structure_material":"鉄筋コンクリート造地下１階地上２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0029","desc":"自然科学教室として建設。本館の右手前、中庭に面して正面を西に向け西校舎に相対するが、正面中央玄関以南が最初に建ち、北半分は後の増築になる。２階建、寄棟屋根の校舎で、スチールサッシ３連の教室窓をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000648"},{"id":"00001842","register_sub_id":"101","register_pk":"102832","name":"東京大学教養学部旧第一高等学校本館（時計台）","kana":"とうきょうだいがくきょうようがくぶきゅうだいいちこうとうがっこうほんかん（とけいだい）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都目黒区駒場3-8","lat":35.66001254,"lng":139.68493528,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2464㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0089","desc":"昭和３年に東大農学部敷地跡に計画された第一高等学校の中心的施設。ロ字形平面，スクラッチタイル貼のＳＲＣ造２階建一部３階建の建物。設計は内田祥三と清水幸重，施工は銭高組で，ゴシック風の外観を呈す東大本郷キャンパスの建築群と意匠的類似性をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001842"},{"id":"00000816","register_sub_id":"101","register_pk":"101806","name":"東京大学工学部１号館","kana":"とうきょうだいがくこうがくぶいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71430893,"lng":139.7600506,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造４階建，建築面積3263㎡","structure_material":"鉄筋コンクリート造４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0037","desc":"旧工科大学本館が関東大震災で損壊したため，その跡地に建築されたもので，昭和１０年に竣工。鉄骨鉄筋コンクリート造で煉瓦タイル貼になる。外観は正面にゴシックアーチのアプローチが付き，各柱筋にバットレス風の付柱を持つ。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000816"},{"id":"00000820","register_sub_id":"101","register_pk":"101810","name":"東京大学工学部列品館","kana":"とうきょうだいがくこうがくぶれっぴんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71325355,"lng":139.7600539,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積766㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0041","desc":"正門の左手奥に建つ建物で，工学部の本部が置かれる。建築途中に震災を受けたが，内田祥三の設計で，彼の震災復興計画に符合する形で完成した最初の建物としても知られる。かつては伊東忠太や関野貞等の収集した中国や朝鮮での調査資料が陳列されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000820"},{"id":"00001762","register_sub_id":"101","register_pk":"102752","name":"東京大学先端科学技術研究センター十三号館（旧東京帝国大学航空研究所本館）","kana":"とうきょうだいがくせんたんかがくぎじゅつけんきゅうせんたーじゅうさんごうかん（きゅうていこくだいがくこうくうけんきゅうじょほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都目黒区駒場4-5","lat":35.66283238,"lng":139.67738869,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階建、建築面積735㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0088","desc":"関東大震災後に越中島から移転した東京帝国大学航空研究所の中心施設。耐震耐火を考慮しＳＲＣ造スクラッチタイル貼とする。地上３階地下１階建，時計台付，全体に９本の水平帯を周し，最上層を縦縞状とする。設計は内田祥三と清水幸重，施工は大倉土木。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001762"},{"id":"00000035","register_sub_id":"101","register_pk":"101025","name":"東京大学大講堂（安田講堂）","kana":"とうきょうだいがくだいこうどう（やすだこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71342334,"lng":139.76229586,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造4階建塔屋付、建築面積1818㎡","structure_material":"鉄筋コンクリート造4階建塔屋付","registered":"1996.12.20(平成8.12.20)","register_no":"13 － 0001","desc":"ゴシック及び表現主義の影響が色濃く見られる垂直性の強いデザインが特徴。外壁は赤茶色のタイル貼りで，意匠的に極めて優秀である。設計は内田祥三，施工は清水組。昭和63年から平成６年にかけて改修が行われている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000035"},{"id":"00000819","register_sub_id":"101","register_pk":"101809","name":"東京大学法学部３号館","kana":"とうきょうだいがくほうがくぶさんごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71262797,"lng":139.76025705,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造４階建，建築面積1727㎡","structure_material":"鉄筋コンクリート造４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0040","desc":"正門のすぐ右手に建つ校舎で，工学部列品館とは東西軸を挟んで向かい合う。正面の出入り口は列品館と同様のゴシックアーチのアーケードを設けるが，東面の意匠は総合図書館と工学部１号館を結ぶ軸線を意識した垂直線を強調する構成になる。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000819"},{"id":"00000817","register_sub_id":"101","register_pk":"101807","name":"東京大学法文１号館","kana":"とうきょうだいがくほうぶんいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71353323,"lng":139.76134764,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造３階建一部４階建，建築面積2695㎡","structure_material":"鉄筋コンクリート造３階建一部４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0038","desc":"東大キャンパスの主軸をなす正門と大講堂を結ぶ東西軸に沿って建つ校舎の一つで，入口ポーチのフィニアルは，旧校舎のものを再用した。１階部分に三廊形式の教会内部を思わせるゴシック様式のアーケードを配し南北通路を跨ぐ構成とする。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000817"},{"id":"00000818","register_sub_id":"101","register_pk":"101808","name":"東京大学法文２号館","kana":"とうきょうだいがくほうぶんにごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71302707,"lng":139.76144415,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造４階建，建築面積3435㎡","structure_material":"鉄筋コンクリート造４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0039","desc":"法文１号館と東西軸を挟んで向かい合う位置に建つ校舎で，１号館同様１階部分にゴシック様式のアーケードを配し通路を設けるが，西端部は法学部３号館を意識したＬ字型の平面構成となる。法文１号館とも，近年４階の１部が増築された。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000818"},{"id":"00000815","register_sub_id":"101","register_pk":"101805","name":"東京大学本郷正門及び門衛所","kana":"とうきょうだいがくほんごうせいもんおよびもんえいじょ","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71294276,"lng":139.75966356,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積46㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0036","desc":"東京大学の正面を飾る一連の施設で，左右対称型に正門・煉瓦塀・門衛所が建ち並ぶ。花崗岩製の正門は，冠木門を基調にデザインされたといわれ，むくり屋根の妻を見せる門衛所とも伝統的な様式形態を保ちつつ新たな時代性を追求している。設計は伊東忠太。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000815"},{"id":"00008260","register_sub_id":"101","register_pk":"133902","name":"東京大学野球場観覧席・ダッグアウト及びフェンス","kana":"とうきょうだいがくやきゅうじょうかんらんせき・だっぐあうとおよびふぇんす","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区弥生1-1-1","lat":35.71880215,"lng":139.76050338,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"観覧席及びダッグアウト 鉄筋コンクリート造3階建、建築面積460㎡、フェンス 鉄筋コンクリート造、延長352m","structure_material":"観覧席及びダッグアウト 鉄筋コンクリート造3階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0259","desc":"東京大学弥生キャンパス内に所在する。内部に記者席、更衣室等を配する階段状の観覧席に、片持ち支持のアーチ形屋根を架ける。観覧席の左右に配されたダッグアウト、グラウンドを囲むフェンスを含め、全体をＲＣでつくる。戦前に遡る数少ない現役の野球場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008260"},{"id":"00001764","register_sub_id":"101","register_pk":"102754","name":"東京農工大学農学部本館","kana":"とうきょうのうこうだいがくのうがくぶほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都府中市幸町3-5-8","lat":35.68421261,"lng":139.48125327,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階、建築面積2896㎡","structure_material":"鉄骨鉄筋コンクリート造3階","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0091","desc":"もと東京高等農林学校本館。Ｅ形平面を持つＳＲＣ造３階建で，中央部に時計台を冠する。外装はモルタル塗を基調とし，軒及び開口部周辺等にスクラッチ及び褐色タイルを貼る。東京帝大農学部実科の本館として計画されたもので，東京帝大営繕課が設計にあたる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001764"},{"id":"00007877","register_sub_id":"101","register_pk":"108857","name":"日本学園一号館","kana":"にほんがくえんいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都世田谷区松原2-735-3他","lat":35.66510615,"lng":139.64897741,"geo_status":"db","era":"昭和11／昭和53・平成7改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1118㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0248","desc":"正面玄関を東に向け、北敷地境と平行して教室棟を配する片廊下型校舎。ＲＣ造３階建、建築面積１１１８㎡。柱梁構造を外観に現し、南面する教室の窓を大きくとる。正門から前庭を介して望む三層分の高さの角柱が並ぶ正面玄関は、正統的で風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007877"},{"id":"00001765","register_sub_id":"101","register_pk":"102755","name":"一橋大学兼松講堂","kana":"ひとつばしだいがくかねまつこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都国立市中2-1","lat":35.69501172,"lng":139.44537877,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積1471㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0092","desc":"東京商科大学国立移転のシンボル的建築。神戸の名士兼松房治郎の13回忌を期に，寄付で建設される。ＲＣ造２階建，外装スクラッチタイル張り，腰石張りで，正面妻面に校章を掲げる。伊東忠太設計のロマネスク風建築として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001765"},{"id":"00001766","register_sub_id":"101","register_pk":"102756","name":"一橋大学旧門衛所","kana":"ひとつばしだいがくきゅうもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国立市中2-1","lat":35.694401,"lng":139.445984,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0093","desc":"東京商科大学の門衛所として建設。２つの校門の間，キャンパスの中心軸線上の緑地帯に位置し，図書館に向きあう。外装はモルタル塗，腰スクラッチタイル矢筈積及び下見板張で，側面に鉄板葺の出窓を設けたフランス瓦葺ハーフティンバーの瀟洒な洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001766"},{"id":"00001767","register_sub_id":"101","register_pk":"102757","name":"一橋大学東本館","kana":"ひとつばしだいがくひがしほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国立市中2-1","lat":35.69557823,"lng":139.44787449,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積1711㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0094","desc":"一橋大学は，堤康次郎の構想による国立学園都市の中核施設として昭和２～５年に神田から移転。大学通り東側のキャンパス地に商学専門部本館として建設される。ロ字形平面ＲＣ造２階建で，兼松講堂と似たロマネスク風の意匠を基調とする。設計は文部省建築課。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001767"},{"id":"00011657","register_sub_id":"101","register_pk":"210673","name":"鎌倉市立御成小学校旧講堂","kana":"かまくらしりつおなりしょうがっこうきゅうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市御成町625-3","lat":35.318187,"lng":139.547823,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積684㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0229","desc":"木造平屋建の講堂。南北棟の入母屋造鋼板葺で、棟上に塔屋二所を設け、小屋はクイーンポストトラスとする。東側面に玄関突出部を配し、内部は講堂の南に準備室二室、北の舞台裏側に控室および用具置場を配す。内外に和洋の要素を併せ持つ、希少な大規模講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011657"},{"id":"00002021","register_sub_id":"101","register_pk":"103011","name":"横浜国立大学教育人間科学部附属横浜中学校校舎（旧横浜高等工業学校本館）","kana":"よこはまこくりつだいがくきょういくにんげんかがくぶふぞくよこはまちゅうがっこうこうしゃ（きゅうよこはまこうとうこうぎょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市南区大岡2-31-3","lat":35.42283131,"lng":139.60291221,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1800㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"14 － 0046","desc":"文部省直轄学校における鉄筋コンクリート造校舎の戦前最後期のもの。両翼を前面に突出させたルネサンス様式的形態をとるが，外観は窓台・まぐさを連続させて水平線を強調するとともに，正面中央に縦長の連続窓を配するなどモダニズム的意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002021"},{"id":"00001567","register_sub_id":"101","register_pk":"102557","name":"横浜国立大学名教自然碑","kana":"よこはまこくりつだいがくめいきょうしぜんひ","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区常盤台79-5","lat":35.47412757,"lng":139.58829601,"geo_status":"db","era":"昭和12／昭和54移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、高さ6.6m","structure_material":"石造","registered":"2000.04.28(平成12.04.28)","register_no":"14 － 0039","desc":"横浜国立大学工学部の前身，横浜高等工業学校の初代校長である鈴木達治の功績を讃えて建てられた。高さ６．６ｍ，方尖柱型の石碑で，設計は同校建築学科教授の中村順平。端整な比例と素材を生かした造形に，気品のある記念性がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001567"},{"id":"00009132","register_sub_id":"101","register_pk":"164685","name":"旧川上小学校体育館","kana":"きゅうかわかみしょうがっこうたいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市牧区切光1438-1","lat":37.08478541,"lng":138.42058062,"geo_status":"db","era":"昭和27年／平成22年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積321㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造平屋1部2階建、建築面積321平方メートル、切妻造鉄板葺。南妻面を入口とし、上部から体育館側に張出す中2階の礼法室を設ける。内部は天井を張らず、トラス組の小屋を現す。地元住民によって建設された、地域教育を象徴する体育館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009132"},{"id":"00014153","register_sub_id":"101","register_pk":"508783","name":"新潟県立加茂農林高等学校正門","kana":"にいがたけんりつかものうりんこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市神明町二丁目15-5","lat":37.66267222,"lng":139.05978889,"geo_status":"db","era":"明治37年／平成30年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造、間口4.6m、脇門柱付","structure_material":"煉瓦造","registered":"2022.02.17(令和4.02.17)","register_no":"15-0565","desc":"前身の農林学校正門として建設された。旧三国街道に面する校地中央に位置する。主門柱は基礎石上に煉瓦のイギリス積の角柱を立て、柱頭は狭間を彫った鉢巻石や、歯形模様付の笠石で飾る。北の脇門柱も同意匠で、表構えを象徴的に演出する重厚な門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014153"},{"id":"00014152","register_sub_id":"101","register_pk":"508782","name":"新潟県立加茂農林高等学校第二洋灯室（ランプ記念館）","kana":"にいがたけんりつかものうりんこうとうがっこうだいにようとうしつ(らんぷきねんかん)","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市神明町二丁目15-5","lat":37.66289167,"lng":139.06180556,"geo_status":"db","era":"明治40年／昭和60年移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積19㎡","structure_material":"煉瓦造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"15-0564","desc":"前身の県立農林学校時代の建設で、寄宿舎で使うランプを消灯時に収容し、清掃や給油も行った。壁は煉瓦のオランダ積で内外とも現しとする。寄棟造桟瓦葺の小屋組はキングポスト・トラス。入口は両開き鉄扉で防火に配慮する。寄宿舎生活を支えた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014152"},{"id":"00008833","register_sub_id":"101","register_pk":"162276","name":"新潟県立長岡高等学校（旧制長岡中學校）正門","kana":"にいがたけんりつながおかこうとうがっこう（きゅうせいながおかちゅうがっこう）せいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市学校町3-14-1","lat":37.44469685,"lng":138.85861222,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、間口10m","structure_material":"煉瓦造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0342","desc":"敷地の西面中央に位置する。煉瓦造、高さ2.7ｍの親柱を6.9ｍ間隔で配し、その北側に高さ2.4ｍの脇柱を設置して通用門とする。頂部には歯飾りや持送を表現した洋風意匠の笠石をのせる。往時の学舎の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008833"},{"id":"00006963","register_sub_id":"101","register_pk":"107945","name":"新潟県立村松高等学校（旧新潟県立工業学校）正門","kana":"にいがたけんりつむらまつこうとうがっこう（きゅうにいがたけんりつこうぎょうがっこう）せいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市村松甲5545","lat":37.68730342,"lng":139.18121357,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造門柱2基、間口4.5m、左側通用門付","structure_material":"煉瓦造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0277","desc":"校舎正面に建つ。門口４．５ｍ、高さ４ｍの門柱一対の片側に通用門を開く。門柱はいずれも煉瓦造で、柱頭にコーニスを付けて飾る。中央の門柱一対はイギリス積で、通用門側の脇柱はフランス積として変化をつける。県下初の工業学校に建てられた、記念碑的な校門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006963"},{"id":"00004951","register_sub_id":"101","register_pk":"105941","name":"新潟大学旭町学術資料展示館（旧新潟師範学校記念館）","kana":"にいがただいがくあさひまちがくじゅつしりょうてんじかん（きゅうにいがたしはんがっこうきねんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区旭町通2-746","lat":37.921192,"lng":139.036621,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積133㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"15 － 0187","desc":"市内に残る初期の鉄筋コンクリート造２階建。昭和初期に流行したネオ・ゴシック様式で，北を正面とし，外壁は１階腰に人造石を廻し，他はスクラッチタイル張とする。正面と両側面は柱型を現し，窓は縦長とする。設計図面から，設計・施工は東京の清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004951"},{"id":"00004952","register_sub_id":"101","register_pk":"105942","name":"新潟大学医学部（旧新潟医学専門学校）表門及び煉瓦塀","kana":"にいがただいがくいがくぶ（きゅうにいがたいがくせんもんがっこう）おもてもんおよびれんがべい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区旭町通1-757","lat":37.92065408,"lng":139.03627852,"geo_status":"db","era":"明治44・大正3／昭和57移設","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"表門 煉瓦造、間柱高さ2.7m、煉瓦塀 煉瓦造、延長149m","structure_material":"表門 煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"15 － 0188","desc":"新潟大学医学部の敷地北辺にある。大正３年建設の表門は煉瓦と白花崗岩の混合積とした高さ２．７ｍの門柱２本からなり，昭和５７年に移設されるが，形式は保持している。明治４４年建設の煉瓦塀は延長１４９ｍで，形状は土地勾配に合わせた階段式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004952"},{"id":"00010765","register_sub_id":"101","register_pk":"201600","name":"旧大鋸屋小学校体育館","kana":"きゅうおがやしょうがっこうたいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市大鋸屋125他","lat":36.499303,"lng":136.900313,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積412㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"16 ‐ 0111","desc":"柱形と柱間の下見板張を意匠的に表した外観をもち、妻壁は二段に迫出して下見板を台形に張り、意匠を凝らす。クイーンポストの小屋組は木材と鋼材を併用し、桁行方向もトラスで固めるという、独特な工法をもつ。県内に残る戦前の木造学校建築として希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010765"},{"id":"00011121","register_sub_id":"101","register_pk":"205228","name":"田中小学校旧本館","kana":"たなかしょうがっこうきゅうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県滑川市加島町230-1","lat":36.759589,"lng":137.333968,"geo_status":"db","era":"昭和11／平成元・同25改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積621㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0120","desc":"木造二階建の校舎。桁行六〇・〇メートル、梁間一〇・〇メートルで、正面側に片廊下を通して背面側に教室等を配する。天井・電気器具・内装木部・手摺などにルネサンス、アールデコ、幾何学模様などを用いるなど、意匠を凝らした昭和前期学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011121"},{"id":"00011665","register_sub_id":"101","register_pk":"210681","name":"富山県立魚津高等学校講堂","kana":"とやまけんりつうおづこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県魚津市吉島945","lat":36.830277,"lng":137.411617,"geo_status":"db","era":"昭和12年／昭和30年・同62年・平成28年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積535㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0121","desc":"桁行二九・三メートル、梁間一六・四メートルの鉄筋コンクリート造講堂。屋根は切妻造で釉薬瓦を葺く。内部は三方にギャラリーを設け、小屋は鉄骨トラスとする。比較的早い時期の鉄筋コンクリート造で、柱型や屋根の端部を立ち上げるなど特色ある意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011665"},{"id":"00012889","register_sub_id":"101","register_pk":"367997","name":"吉江地区招魂社（旧吉江小学校奉安殿）","kana":"よしえちくしょうこんしゃ（きゅうよしえしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市荒木725","lat":36.55521389,"lng":136.88071111,"geo_status":"db","era":"昭和5年／昭和32年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造平屋建、金属板葺、建築面積3.5㎡","structure_material":"石造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 146","desc":"地区公園の一角にあり、高い二重基壇上に北面して建つ。石造で、方形の主体部前面にエンタシス付の柱を立て、アーキトレーブと大振りのコーニスを廻し、切妻造の屋根を載せる。西洋古典様式を取り入れた和洋折衷の上質なつくりで、戦前の奉安殿の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012889"},{"id":"00014795","register_sub_id":"101","register_pk":"519053","name":"金沢大学医学類（旧制金沢医学専門学校）西面北煉瓦塀","kana":"かなざわだいがくいがくるい（きゅうせいかなざわいがくせんもんがっこう）にしめんきたれんがべい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55535278,"lng":136.67289722,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造、延長18m","structure_material":"煉瓦造","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0316","desc":"敷地南西面、北西端に残る延長18メートルの煉瓦塀。道路との間に水路を設け、その敷地側に低い煉瓦塀を築く。切石積基礎及び延石の上に煉瓦を積み、人造石洗出の笠石を載せる。旧制金沢医学専門学校時代の貴重な遺構で、通りに沿って歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014795"},{"id":"00014794","register_sub_id":"101","register_pk":"519052","name":"金沢大学医学類（旧制金沢医学専門学校）西面南旧正門及び煉瓦塀","kana":"かなざわだいがくいがくるい（きゅうせいかなざわいがくせんもんがっこう）にしめんみなみきゅうせいもんおよびれんがべい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55460833,"lng":136.67386389,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"旧正門控柱 石造、塀 煉瓦造、総延長202m","structure_material":"旧正門控柱 石造","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0315","desc":"敷地西面南、旧正門を挟んで道路に沿った総延長二○二メートルの低い煉瓦塀。旧正門は主門柱を欠失するが、花崗岩切石造の脇門柱が二本残る。塀は基礎及び延石を切石積、壁体を煉瓦積、笠石を人造石洗出仕上とする。旧制金沢医学専門学校時代の貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014794"},{"id":"00014792","register_sub_id":"101","register_pk":"519050","name":"金沢大学医学類解剖標本庫（旧制金沢医科大学解剖学標本庫）","kana":"かなざわだいがくいがくるいかいぼうひょうほんこ（きゅうせいかなざわいかだいがくかいぼうがくひょうほんこ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55583333,"lng":136.67489722,"geo_status":"db","era":"昭和9年／昭和61年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積194㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0313","desc":"旧制金沢医科大学の解剖標本庫。鉄筋コンクリート造平屋建陸屋根。外壁スクラッチタイル貼。柱形の列柱をみせ、各間に窓を開き、簡素ながらも重厚な意匠。内部は一室の土間で標本を陳列した木製棚を並べる。大学草創期の医学研究・教育の実像を現在に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014792"},{"id":"00014791","register_sub_id":"101","register_pk":"519049","name":"金沢大学医学類旧書庫（旧制金沢医科大学附属図書館書庫）","kana":"かなざわだいがくいがくるいきゅうしょこ（きゅうせいかなざわいかだいがくふぞくとしょかんしょこ）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55548611,"lng":136.67425,"geo_status":"db","era":"大正15年／昭和60年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積142㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0312","desc":"旧制金沢医科大学の図書館書庫。鉄筋コンクリート造三階建陸屋根。外壁は人造石洗出、四隅に柱形を付け、各間に縦長窓を配し、直方体の外観に変化を付ける。内部は各階一室で廻り階段中央に当初の昇降機が残る。草創期からの貴重な鉄筋コンクリート造書庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014791"},{"id":"00014793","register_sub_id":"101","register_pk":"519051","name":"金沢大学医学類病理標本庫（旧制金沢医科大学病理学標本庫）","kana":"かなざわだいがくいがくるいびょうりひょうほんこ（きゅうせいかなざわいかだいがくびょうりがくひょうほんこ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55645556,"lng":136.67466944,"geo_status":"db","era":"大正15年／昭和60年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積99㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0314","desc":"旧制金沢医科大学の病理標本庫。鉄筋コンクリート造二階建陸屋根。外壁は人造石洗出、柱形をみせ、窓廻りに煉瓦を貼り、簡素ながらも整然とした意匠。内部は各階一室とし、独立柱を立て、柱型と梁で繋ぐ。大学草創期から残り、構内の歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014793"},{"id":"00012896","register_sub_id":"101","register_pk":"367999","name":"川上幼稚園園舎","kana":"かわかみようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市幸町378他","lat":36.55324167,"lng":136.65918889,"geo_status":"db","era":"大正7年頃／昭和40年頃・平成23年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積299㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 285","desc":"市街地南部の住宅地にあり、敷地後方に東面して建つ。木造二階建、切妻造桟瓦葺妻入で、正面下屋の北端に玄関ポーチを突出する。外壁下見板張。トラス小屋組。上下階南半を大部屋として保育室にあてる。近代住宅地の閑静な景観に調和し、地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012896"},{"id":"00014798","register_sub_id":"101","register_pk":"519056","name":"旧第四高等中学校門衛所","kana":"きゅうだいしこうとうちゅうがっこうもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市広坂二丁目65-2","lat":36.56228611,"lng":136.65561111,"geo_status":"db","era":"明治26年／大正8年改修、昭和42年移築、令和5年改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0319","desc":"旧第四高等中学校本館の南西に位置する門衛所。平屋建切妻造桟瓦葺の東西棟で、東西に庇を付す。外壁は下見板張とし、上下窓を開け、東西妻面にガラリを設ける。内部は三室に仕切り、北西旧の詰所は出窓を付す。本館とともに歴史的な景観を形成する門衛所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014798"},{"id":"00008669","register_sub_id":"101","register_pk":"149390","name":"小浜市立小浜中学校洗心館（旧福井県立小浜尋常中学校図書館）","kana":"おばましりつおばまちゅうがっこうせんしんかん（きゅうふくいけんりつおばまじんじょうちゅうがっこうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県小浜市雲浜2-1-1","lat":35.5067391,"lng":135.74673013,"geo_status":"db","era":"昭和7年／昭和中期移築増築","year":1932,"year_source":"converted","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0090","desc":"北川の河口北岸にある校地の西南隅に位置する。桁行15ｍ梁間9.1ｍ、寄棟造桟瓦葺、北面玄関附属。1.8ｍ間隔で柱を整然と配り、木造キングポストトラスを架ける。外壁下見板張、小壁漆喰塗など、当時の設計基準に準拠した標準的な木造図書館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008669"},{"id":"00010770","register_sub_id":"101","register_pk":"201605","name":"福井鉄道バス旧車庫","kana":"ふくいてつどうばすきゅうしゃこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県越前市北府二丁目5字中藤牧3-2","lat":35.91073,"lng":136.165937,"geo_status":"db","era":"大正8／昭和31頃移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0138","desc":"北府駅車両工場の西側に近接して建つ。桁行二七メートル梁間一五メートル、切妻造の東西に長い木造平屋建で、両妻面にはバスが出入りする一〇メートル幅の開口部を設ける。小学校の講堂をバス車庫に転用した木造建築で、交通施設の近代化の一面を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010770"},{"id":"00000207","register_sub_id":"101","register_pk":"101197","name":"塩山市中央区区民会館（旧千野学校校舎）","kana":"えんざんしちゅうおうくくみんかいかん（きゅうちのがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山上於曽1157","lat":35.70692062,"lng":138.7290086,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建，瓦葺，建築面積129㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"19 － 0009","desc":"いわゆる藤村式の学校建築で、学校廃校後昭和２３年に現在地に移築され、警察署や図書館分館として使用された。寄棟造、２階建の正面に切妻造の玄関棟が附属する独特の外観は、改造があるが、校舎としての面影を残しており、多くの人々に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000207"},{"id":"00014358","register_sub_id":"101","register_pk":"511347","name":"山梨英和中学校・高等学校講堂グリンバンク・チャペル","kana":"やまなしえいわちゅうがっこう・こうとうがっこうこうどうぐりんばんく・ちゃぺる","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県甲府市愛宕町112","lat":35.66713333,"lng":138.57505833,"geo_status":"db","era":"昭和24年／同40年頃・平成17年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造及び木造3階建、スレート葺、建築面積379㎡","structure_material":"鉄筋コンクリート造及び木造3階建","registered":"2022.10.31(令和4.10.31)","register_no":"19 - 0166","desc":"甲斐の山なみ背にするミッションスクールのチャペルで設計は塩川旭。1階は鉄筋コンクリート造煉瓦貼、２・３階の講堂は木造モルタル仕上、屋根は切妻造Ｔ字形スレート葺。講堂はキングポスト・トラスの合掌材を勾配天井に巧みに隠し、洗練された吹抜とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014358"},{"id":"00013385","register_sub_id":"101","register_pk":"368471","name":"山梨大学水晶庫","kana":"やまなしだいがくすいしょうこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市武田四丁目74-1","lat":35.67909722,"lng":138.57348889,"geo_status":"db","era":"昭和2年／平成30年移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積40㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0148","desc":"山梨大学甲府キャンパスの正門北側に位置し、西面して建つ。鉄筋コンクリート造平屋建てで、内部は水晶の展示室と倉庫の二室に分かれる。四面に配した窓の上部に、水晶をモチーフにしたレリーフを飾る。山梨県内の初期の鉄筋コンクリート造建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013385"},{"id":"00005164","register_sub_id":"101","register_pk":"106154","name":"飯田市立追手町小学校校舎","kana":"いいだしりつおうてまちしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯田市追手町2-673-1","lat":35.513035,"lng":137.829208,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積3753㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0232","desc":"敷地の北辺一杯に建つＲＣ造３階建校舎。東西両端を円弧として校庭側にわずかに折った平面をもつ。一般教室は４間に５間の規模である。昇降口は円弧部に設け，竪溝付の円柱，三中心アーチ，短い庇で飾る。長大な外壁は柱形を強調してリズムを造り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005164"},{"id":"00005165","register_sub_id":"101","register_pk":"106155","name":"飯田市立追手町小学校講堂","kana":"いいだしりつおうてまちしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯田市追手町2-673-1","lat":35.512287,"lng":137.829102,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨造平屋建、鉄板葺、建築面積893㎡","structure_material":"鉄骨造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0233","desc":"敷地の南辺東寄りに建つ鉄骨造，平屋建で，桁行２５間，梁間１０間。半切妻屋根を鉄板葺とする。外壁は付柱に下見板張で，出入口には切妻庇がつく。内壁は白漆喰塗で，腰を竪羽目板張とし，室内を折上格天井とし，鉄骨構造部材を見せない形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005165"},{"id":"00009455","register_sub_id":"101","register_pk":"194248","name":"旧麻績小学校北校舎","kana":"きゅうおみしょうがっこうきたこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県東筑摩郡麻績村麻字苗代3848-4他","lat":36.45713075,"lng":138.04497485,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積621㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"20 － 0426","desc":"木造二階建、桁行五四・五メートル梁間一〇メートル、寄棟造桟瓦葺で、正面中央に玄関ポーチ、背面に階段室二箇所を張出す。外壁は白色スレート板横張とし、内部は片廊下式で各室や廊下の天井を斜めに折上げる。長野県内における昭和前期の校舎の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009455"},{"id":"00003423","register_sub_id":"101","register_pk":"104413","name":"旧常田幼稚園園舎","kana":"きゅうときたようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田2-30-17","lat":36.39662517,"lng":138.25688028,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0130","desc":"木造２階建，建築面積１９４㎡で，設計はヴォーリズ合名会社による。外壁はモルタル塗ドイツ壁風仕上で，切妻造，桟瓦葺の長方形平面を基本とし，正面に遊戯室をベイウィンドー状に突出させた左右対称の構成をなす。小振りな幼稚園建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003423"},{"id":"00005166","register_sub_id":"101","register_pk":"106156","name":"旧山本中学校杵原校舎管理教室棟","kana":"きゅうやまもとちゅうがっこうきねはらこうしゃかんりきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県飯田市竹佐377-1","lat":35.467678,"lng":137.766342,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積609㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0234","desc":"敷地の北寄りに建つ東西棟で，桁行３５間，梁間５間余の木造平屋建である。切妻造，桟瓦葺で，南面中央に寄棟造の玄関ポーチを突出する。外壁は下見板張で，小壁を白漆喰塗とする。内部は壁を白漆喰塗，腰を竪羽目板張とし，教室，廊下共に竿縁天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005166"},{"id":"00005167","register_sub_id":"101","register_pk":"106157","name":"旧山本中学校杵原校舎教室棟","kana":"きゅうやまもとちゅうがっこうきねはらこうしゃきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県飯田市竹佐377-1","lat":35.467888,"lng":137.766357,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積768㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0235","desc":"管理教室棟と同規模で北側に並ぶ。教室は桁行５間，梁行４間規模で７室並び，北側に幅７．５尺の廊下が通る。建物東西端の渡廊下で南の管理教室棟と接続する。外回りには欄間付の引違い窓を３連一組で配し，教室と廊下の境には欄間無しの引違い窓を建て込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005167"},{"id":"00003233","register_sub_id":"101","register_pk":"104223","name":"金鵄会館（長野県長野高等学校旧南校舎）","kana":"きんしかいかん（ながのけんながのこうとうがっこうきゅうみなみこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市大字上松1-824-1","lat":36.66925299,"lng":138.19879602,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積752㎡、塔屋付","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0120","desc":"木造２階建校舎で，正面側１階をモルタル仕上げ，２階をドイツ下見とし，ほぼ中央に玄関車寄を突出させる。中央部の前面はタイル張とし，宝形屋根を戴く塔屋を立ち上げる。教室の連続窓風の横長窓と塔屋部及び車寄の造形意匠に時代の特徴がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003233"},{"id":"00010970","register_sub_id":"101","register_pk":"208940","name":"三水第一小学校茶室","kana":"さみずだいいちしょうがっこうちゃしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県上水内郡飯綱町大字普光寺179","lat":36.761662,"lng":138.251966,"geo_status":"db","era":"昭和17／昭和58移築","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0499","desc":"茶道を通じた学習の場として建築された。三畳と四畳半の茶室二間が水屋を共有する平面で、四畳半の二辺に矩折れに入側縁を廻らす。三畳茶室は躙り口を備え、掛込天井とする。四畳半茶室は柱を面皮付とし、コブシの皮付丸太を床柱とする数寄屋風である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010970"},{"id":"00000763","register_sub_id":"101","register_pk":"101753","name":"信州大学繊維学部講堂（旧上田蚕糸専門学校講堂）","kana":"しんしゅうだいがくせんいがくぶこうどう（きゅううえださんしせんもんがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市常田3-15-1","lat":36.39212915,"lng":138.26142788,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積357㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0005","desc":"養蚕業の盛んなこの地方で繊維教育のために設立された上田蚕糸専門学校の講堂として建てられた。木造下見板貼の上質な建築で，玄関部の三角に張り出す窓の形状は特異。内部には蚕糸に因んだ彫刻がある。設計は文部省（建築課長は柴垣鼎太郎），施工は柳屋組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000763"},{"id":"00009597","register_sub_id":"101","register_pk":"194593","name":"信州大学繊維学部守衛所（旧上田蚕糸専門学校門衛詰所）","kana":"しんしゅうだいがくせんいがくぶしゅえいじょ（きゅううえださんしせんもんがっこうもんえいつめしょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田3-480他","lat":36.3928483,"lng":138.26005049,"geo_status":"db","era":"大正元／昭和4・昭和39移築・昭和45改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0428","desc":"大学正門北脇に建つ。木造平屋建、寄棟造鋼板葺の小規模な建物。正面は両角を隅切した半八角平面で事務室と窓口を設け、背面に畳敷の休憩室を置く。外観は下見板張とし窓上部や棟飾りに装飾を配する。学内で二度の移築を経てなお学舎の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009597"},{"id":"00009596","register_sub_id":"101","register_pk":"194592","name":"信州大学繊維学部資料館（旧上田蚕糸専門学校貯繭庫）","kana":"しんしゅうだいがくせんいがくぶしりょうかん（きゅううえださんしせんもんがっこうちょけんこ）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市常田3-480他","lat":36.39291969,"lng":138.26296295,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積67㎡","structure_material":"煉瓦造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0427","desc":"大学構内中央北寄りに位置する。煉瓦造二階建、寄棟造桟瓦葺で、外壁に柱形を表し、各間中央は窓とし鉄扉両開とする。開口上部は一階は欠円アーチ、二階はフラットアーチとし意匠を引き立てる。繭の保管庫として建築された貯繭庫の特徴を良好に残す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009596"},{"id":"00012148","register_sub_id":"101","register_pk":"352947","name":"筑波大学山岳科学センター菅平高原実験所大明神寮","kana":"つくばだいがくさんがくかがくせんたーすがだいらこうげんじっけんしょだいみょうじんりょう","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県上田市菅平高原1278-294","lat":36.522915,"lng":138.348672,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"20-519","desc":"高原の緩斜面に建つ。東西に長い木造平屋建、切妻造で、外壁下見板張。北側に廊下を通し、東寄りに八畳四室、西寄りに食堂と厨房、風呂などを配する。各室の南面に出窓を設けて二重窓とし採光と断熱を図り、寒冷な気候に対処する。特異な環境下の大学宿舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012148"},{"id":"00012534","register_sub_id":"101","register_pk":"367829","name":"東京藝術大学山岳部黒沢ヒュッテ","kana":"とうきょうげいじゅつだいがくさんがくぶくろさわひゅって","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長野県","address":"長野県大町市平字黒沢4976-3","lat":36.498711,"lng":137.734756,"geo_status":"geocoded","era":"昭和35年／平成10年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造及びコンクリートブロック造2階建、金属板葺、建築面積79㎡","structure_material":"木造及びコンクリートブロック造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0537","desc":"標高1200メートルの尾根上に建つ大学山岳部の山小屋で、折板状の片流れ屋根の軒を深く張出す。コンクリートブロック造の一階は寝室、木造の二階は居間中心で南西面に広い開口を設け、テラスから後立山連峰を望む。戦後の登山ブームの一端を示す山岳施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012534"},{"id":"00003240","register_sub_id":"101","register_pk":"104230","name":"長野県松本深志高等学校管理普通教室棟","kana":"ながのけんまつもとふかしこうとうがっこうかんりふつうきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市蟻ケ崎3-8-1","lat":36.24745783,"lng":137.96637403,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2579㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0127","desc":"長野県内における初期鉄筋コンクリート造学校建築。３階建，スクラッチタイル張で，正面中央玄関ポーチの緩やかな尖頭アーチ，２階３階通しの先を尖らせた柱型などゴシック風意匠に特徴。東京帝大安田講堂（東京大学大講堂）が手本と伝える。県営繕の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003240"},{"id":"00003241","register_sub_id":"101","register_pk":"104231","name":"長野県松本深志高等学校講堂","kana":"ながのけんまつもとふかしこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市蟻ケ崎3-8-1","lat":36.247726,"lng":137.966843,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積835㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0128","desc":"体育館を兼ねた講堂。壁体は鉄筋コンクリート造とし，山形の鉄骨トラスで桟瓦葺の切妻屋根を支持する。南妻面には先を尖らせた柱型を表し，５連の尖頭アーチによるアーケード風正面玄関を設けスクラッチタイルを張るなど管理普通教室棟に呼応した意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003241"},{"id":"00007634","register_sub_id":"101","register_pk":"108616","name":"長野県南安曇農業高等学校第二農場日輪舎","kana":"ながのけんみなみあづみのうぎょうこうとうがっこうだいにのうじょうにちりんしゃ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県安曇野市堀金烏川1773-2","lat":36.303986,"lng":137.862274,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積139㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0351","desc":"直径１３ｍ規模で、ほぼ円形平面とする木造総２階建。外壁を下見板張とし、軒天井を板張、入口に庇をかけ、簡素な持送りを付ける。壁面全方向に幅広の窓をとり採光を確保する。円筒形の躯体に円錐形の屋根をかける独特の外観で、全国的にも残存例が少ない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007634"},{"id":"00008982","register_sub_id":"101","register_pk":"162342","name":"松商学園高等学校講堂","kana":"まつしょうがくえんこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市県3-2301-4他","lat":36.22966721,"lng":137.98623137,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積741㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0379","desc":"本館東側に建ち、鉄筋コンクリート造、桁行三六・九メートル梁間一九・五メートル、切妻造妻入、鉄板葺である。妻面は中央に細い柱形を三本立てて外観を引き締め、側面は臥梁と外面を揃えた高い柱形を見せる。昭和初期における鉄筋コンクリート造講堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008982"},{"id":"00008983","register_sub_id":"101","register_pk":"162343","name":"松商学園高等学校柔剣道場","kana":"まつしょうがくえんこうとうがっこうじゅうけんどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市県3-2301-4他","lat":36.22954098,"lng":137.98461944,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積595㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0380","desc":"本館西側に建ち、鉄筋コンクリート造二階建、桁行３６．４ｍ梁間１６．４ｍ、切妻造妻入、鉄板葺である。外観は講堂と同様に高い柱形を見せ、各間に半円アーチ形を現し、アーチ窓や矩形窓を配置する。本館、講堂とともに特徴的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008983"},{"id":"00008981","register_sub_id":"101","register_pk":"162341","name":"松商学園高等学校本館","kana":"まつしょうがくえんこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県松本市県3-2312-2他","lat":36.229473,"lng":137.98543511,"geo_status":"db","era":"昭和11年／昭和54年・平成21年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1140㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0378","desc":"校地北辺中央に北面して建ち、木造二階建、建築面積１１４０㎡、入母屋造桟瓦葺である。中央に張出した入母屋屋根の玄関に石造風のポーチを設ける。外壁を下見板張、屋根に千鳥破風を配するなど和洋の意匠を折衷した、大型の木造校舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008981"},{"id":"00014830","register_sub_id":"101","register_pk":"519090","name":"加藤学園暁秀初等学校本館","kana":"かとうがくえんぎょうしゅうしょとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和後","pref":"静岡県","address":"静岡県沼津市岡宮字八島348-2他","lat":35.11755,"lng":138.86899444,"geo_status":"db","era":"昭和47年／平成17年・令和3年改修","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積2，228㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0325","desc":"市街の校地北端に建つ鉄筋コンクリート造校舎。設計は槇総合計画事務所。学習センターを中心に中庭を介して普通教室などを配し、界壁を極力省き開放性を高める。多様な自然採光、色彩豊かな室内グラフィックも秀逸。日本初オープンプランスクールとして重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014830"},{"id":"00010974","register_sub_id":"101","register_pk":"208944","name":"旧気多村立勝坂小学校校舎","kana":"きゅうけたそんりつかつさかしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県浜松市天竜区春野町豊岡字キタノシマ240-3他","lat":35.06246,"lng":137.913681,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積208㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"22-0218","desc":"外壁下見板張の校舎。当初から複式学級を想定し、一階に職員室と普通教室、二階に講堂兼特別教室を配す。柱の添柱や小屋の方杖、採光に配慮して広めた窓部や反射光を取り入れる中庇などに当時の学校建築の特徴を示す。山村風景に彩りを添える木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010974"},{"id":"00011507","register_sub_id":"101","register_pk":"210466","name":"旧中村洋裁学院","kana":"きゅうなかむらようさいがくいん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県袋井市袋井260-1","lat":34.74693389,"lng":137.92325389,"geo_status":"db","era":"昭和25年／昭和28年増築、平成24年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0234","desc":"原野谷川沿いに南北棟で建つ。木造二階建、切妻造桟瓦葺で、棟端のフィニアルに校章を表す。外壁下見板張で妻にガラリを付け、軒天井を廻す。内部は上下階とも南半を広い一室の教室とし、北半に和室・洋室を配する。戦後復興期の各種学校校舎の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011507"},{"id":"00002395","register_sub_id":"101","register_pk":"103385","name":"静岡県立磐田農業高等学校記念館","kana":"しずおかけんりついわたのうぎょうこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市中泉168","lat":34.71601035,"lng":137.853149,"geo_status":"db","era":"明治42／昭和60移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"22 － 0076","desc":"県立農学校が見付町から中泉地区に移転してきた時に講堂として建設。桁行１７．５ｍ，梁間１２ｍ，寄棟造，桟瓦葺で，外壁は下見板張とし，上げ下げの単窓を連ね，正面妻側に後年改装のアーチ型の玄関ポーチを張り出す。明治後期公立学校建築遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002395"},{"id":"00004976","register_sub_id":"101","register_pk":"105966","name":"豊門公園西洋館（旧豊門青年学校）","kana":"ほうもんかいかんせいようかん（きゅうほうもんせいねんがっこう）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.36287766,"lng":138.98616463,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、スレート葺、建築面積235㎡、塔屋付","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0102","desc":"豊門公園の北側に南面して建つ。木造２階建，スレート葺で，寄棟造，外装下見板張とし，欄間付縦長窓を四周に配す。正面中央に設けられた車寄付塔屋の左右で２階壁面を前後させ，西半は帯状の小壁を巡らして外観を引き締める等，変化に富んだ瀟洒な洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004976"},{"id":"00000434","register_sub_id":"101","register_pk":"101424","name":"愛知学院大学楠元学舎第１号館","kana":"あいちがくいんだいがくくすもとがくしゃだいいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区楠元町1-1","lat":35.16702318,"lng":136.96146983,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積805㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"23 － 0008","desc":"旧制愛知中学本館として建てられた。中央部は玄関ポーチを設け壁を立ち上げ正面性を強調し，左右に翼屋をのばす。スクラッチタイル貼りの外壁，１・２階を通した柱形，柱形頂部の庇状の装飾等に時代の特徴があらわれている。設計佐藤三郎，施工西村工務店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000434"},{"id":"00011709","register_sub_id":"101","register_pk":"210725","name":"愛知県立旭丘高等学校正門門柱（旧愛知県立第一中学校正門）","kana":"あいちけんりつあさひがおかこうとうがっこうせいもんもんちゅう（きゅうあいちけんだいいちちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区出来町三丁目6-15","lat":35.183821,"lng":136.938729,"geo_status":"db","era":"昭和13年／昭和34年・平成13年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、間口8.2m、北方脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0479","desc":"愛知県第一中学校の現在地への移転に際して建設された。主柱はほぼ正方形平面で、四隅を切り欠く。高さは二・四メートルで、鉄筋コンクリート造。脇柱は九割程度の大きさで、いずれも横目地四本を切る。重厚な意匠で、県下の教育の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011709"}];
